  ('KIM-0019', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'qapali', 'Verilmiş duzun adını və tipini müəyyən edin. $\mathrm{MgHPO_{4}}$ Duzun tipi Adı', 'KIM-0019.png', '{"A": "maqnezium-dihidroortofosfat turş", "B": "maqnezium-hidroortofosfat turş", "C": "maqnezium-ortofosfat normal", "D": "maqnezium-hidroortofosfat normal", "E": "maqnezium-metafosfat qarışıq"}', 'B', '3', '$\mathrm{MgHPO_{4}}$ – maqnezium-hidroortofosfat, turş duzdur', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №49', 'KIM-0019_izah.png'),
  ('KIM-0020', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Hansı duzun termiki parçalanmasından həm əsasi, həm də turşu oksidi əmələ gəlir?', NULL::text, '{"A": "$\\mathrm{Cu(NO_{3})_{2}}$", "B": "$\\mathrm{NaNO_{3}}$", "C": "$\\mathrm{AgNO_{3}}$", "D": "$\\mathrm{NH_{4}NO_{3}}$", "E": "$\\mathrm{KNO_{3}}$"}', 'A', '3', '$\mathrm{Cu(NO_{3})_{2} \rightarrow CuO}$ (əsasi oksid) + $\mathrm{NO_{2}}$ (turşu oksidi) + $\mathrm{O_{2}}$ $\mathrm{NaNO_{3} \rightarrow NaNO_{2} + O_{2}}$ $\mathrm{AgNO_{3} \rightarrow Ag + NO_{2} + O_{2}}$ $\mathrm{NH_{4}NO_{3} \rightarrow N_{2}O + H_{2}O}$ $\mathrm{KNO_{3} \rightarrow KNO_{2} + O_{2}}$', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №50', 'KIM-0020_izah.png'),
  ('KIM-0021', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', '$\mathrm{Fe}$ $\mathrm{Ag}$ $\mathrm{Zn}$ Hər 3 qabda 200 q 16%-li $\mathrm{CuSO_{4}}$ məhlulu olduğunu nəzərə alaraq, $\mathrm{CuSO_{4}}$ məhlulu ilə metal lövhələrin tam reaksiyası zamanı alınan misin kütlələri cəmini qramla hesablayın. $\mathrm{M_{r}(CuSO_{4})=160,}$ $\mathrm{A_{r}(Cu)=64}$', 'KIM-0021.png', '{"A": "12,8", "B": "25,6", "C": "128", "D": "64", "E": "33,6"}', 'B', '3', 'Hər 3 qabda $\mathrm{CuSO_{4}}$ – ün kütləsi: $\mathrm{m(CuSO_{4})}$ = 200 ⋅ 0,16 = 32 q 32 q x q $\mathrm{Fe + CuSO_{4} \rightarrow FeSO_{4} + Cu}$ x = 12,8 q 160 q 64 q $\mathrm{Ag + CuSO_{4}}$ → reaksiya getmir 32 q y q $\mathrm{Zn + CuSO_{4} \rightarrow ZnSO_{4} + Cu}$ y = 12,8 q 160 q 64 q Reaksiyalardan alınan $\mathrm{Cu}$-un kütləsi = 12,8 + 12,8 = 25,6 q', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №51', 'KIM-0021_izah.png'),
  ('KIM-0023', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'aciq_eded', 'Bərabər mol nisbətində götürülən butadien-1,3 və stiroldan alınan birgə polimerin kütləsi 316 kq-dır. Polimerləşmə reaksiyasına neçə kq stirol daxil olmuşdur? $\mathrm{M_{r}(C_{4}H_{6})}$ =54, $\mathrm{M_{r}(C_{6}H_{5}}$ $\mathrm{CH}$ $\mathrm{CH_{2})}$ =104', NULL::text, NULL::text, '208', '3', 'Birgə polimerləşmə reaksiyasında butadien-1,3 və stirol 2 : 2 nisbətində götürüldükdə 2 ⋅ 54 + 2 ⋅ 104 = 316 kq polimer əmələ gəlir. Reaksiyaya 208 kq stirol daxil olub.', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №53', 'KIM-0023_izah.png'),
  ('KIM-0024', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'aciq_eded', 'Etilen və asetilendən ibarət qaz qarışığının 12 molunun tam hidrogenləşməsinə 20 mol $\mathrm{H_{2}}$ sərf olunmuşsa, ilkin qaz qarışığında neçə mol asetilen olmuşdur?', NULL::text, NULL::text, '8', '3', 'Etilen və asetilendən ibarət 12 mol qaz qarışığında etilenin mol sayını x, asetilenin mol sayını y mol qəbul etsək x + y = 12 olur. Etilenin 1 molunun tam hidrogenləşməsinə 1 mol $\mathrm{H_{2}}$ ,asetilenin 1 molunun tam hidrogenləşməsinə isə 2 mol $\mathrm{H_{2}}$ sərf olunur: x + y = 12 x + 2y = 20 x = 4 y = 8 (Deməli ilkin qarışıqda 8 mol asetilen olmuşdur)', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №54', 'KIM-0024_izah.png'),
  ('KIM-0026', 'Ümumi kimya', 'Məhlullar', 'aciq_eded', '$\mathrm{H_{2}SO_{4}}$ məhlulunun kütləsi, q Artıq miqdar $\mathrm{BaCl_{2}}$ məhlulu ilə reaksiyadan alınan çöküntünün kütləsi, q 49 23,3 Başlanğıc məhlulda sulfat turşusunun kütlə payını (% ilə) hesablayın. $\mathrm{M_{r}(H_{2}SO_{4})=98}$; $\mathrm{M_{r}(BaSO_{4})=233}$', 'KIM-0026.png', NULL::text, '20', '3', 'x q ------------------- 23,3 q $\mathrm{H_{2}SO_{4} + BaCl_{2} \rightarrow BaSO_{4}}$ ↓ + $\mathrm{2HCl}$ x = 9,8 q $\mathrm{H_{2}SO_{4}}$ 98 q ------------------- 233 q Məhlulda sulfat turşusunun kütlə payı = (9,8 : 49) ⋅ 100 = 20%', '{4}', '2026', '2026-07-12 qəbul, IV qrup, A variantı №56', 'KIM-0026_izah.png'),
  ('KIM-0031', 'Üzvi kimya', 'Karbon turşuları', 'qapali', 'Maddə Molekulunda σ(C–H) rabitələrinin sayı Siniflərarası izomerinin hidroliz məhsulları $\mathrm{C_{n}H_{2n+1}COOH}$ 5 X+Y Y “gümüş-güzgü” reaksiyasına daxil olursa, X molekulunda atomların ümumi sayını hesablayın.', 'KIM-0031.png', '{"A": "5", "B": "12", "C": "6", "D": "9", "E": "8"}', 'D', '3', '2n + 1 = 5 2n = 4 n = 2 $\mathrm{C_{2}H_{5}COOH}$ turşusu ilə siniflərarası izomer olan maddənin hidroliz tənliyi: $\mathrm{HCOOC_{2}H_{5}+}$ $\mathrm{H_{2}O \Leftrightarrow HCOOH + C_{2}H_{5}OH}$ $\mathrm{HCOOH}$ “gümüş-güzgü” reaksiyasına daxil olduğu üçün X maddəsi $\mathrm{C_{2}H_{5}OH}$-dır və molekulunda 9 atomu var.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №31', 'KIM-0031_izah.png'),
  ('KIM-0032', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Eyni kütlədə götürülmüş hidrogen və etandan ibarət qarışığın ümumi mol miqdarı 16 olarsa, hansı ifadələr doğrudur? $\mathrm{M_{r}(H_{2})=2,}$ $\mathrm{M_{r}(C_{2}H_{6})=30}$ I. Qarışığın ümumi kütləsi 60 qramdır II. Qarışıqda etanın həcmi 22,4 l-dir (n.ş.) III. Qarışıqda hidrogenin həcmi 22,4 l-dir (n.ş.)', NULL::text, '{"A": "yalnız II", "B": "I, III", "C": "I, II", "D": "II, III", "E": "yalnız I"}', 'C', '3', '16 30 2 15 16 30 16 16 30 30 m m m m m m + = + = = = Qarışığın ümumi kütləsi 30 + 30 = 60 q 30 q $\mathrm{C_{2}H_{6}}$ = 1 mol = 22,4 l 30 q $\mathrm{H_{2}}$ = 15 mol = 336 l', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №32', 'KIM-0032_izah.png'),
  ('KIM-0033', 'Ümumi kimya', 'Kimyəvi rabitə və hibridləşmə', 'qapali', 'Maddələr Molekulunda kimyəvi rabitələrin yaranmasında iştirak edən hibrid orbitallarının sayı X 4 Y 3 Z 2 X, Y və Z maddələrini müəyyən edin. X Y Z', 'KIM-0033.png', '{"A": "$\\mathrm{CH_{4}}$ $\\mathrm{NH_{3}}$ $\\mathrm{H_{2}O}$", "B": "$\\mathrm{CH_{4}}$ $\\mathrm{H_{2}O}$ $\\mathrm{NH_{3}}$", "C": "$\\mathrm{H_{2}O}$ $\\mathrm{NH_{3}}$ $\\mathrm{CH_{4}}$", "D": "$\\mathrm{NH_{3}}$ $\\mathrm{H_{2}O}$ $\\mathrm{CH_{4}}$", "E": "$\\mathrm{NH_{3}}$ $\\mathrm{CH_{4}}$ $\\mathrm{H_{2}O}$"}', 'A', '3', 'Hər üç molekulda mərkəzi atom $\mathrm{sp^{3}}$ hibrid halında olub 4 hibrid orbitalına malikdir. $\mathrm{CH_{4}}$ molekulunda 4 hibrid orbitalının hamısı, $\mathrm{NH_{3}}$ molekulunda 3-ü, $\mathrm{H_{2}O}$ molekulunda isə 2-si rabitələrin yaranmasında iştirak edir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №33', 'KIM-0033_izah.png'),
  ('KIM-0034', 'Ümumi kimya', 'Elektroliz', 'qapali', 'Duzun tam elektrolizi zamanı Y elektrodunda əmələ gələn maddənin kütləsini (q) hesablayın. $\mathrm{A_{r}(Cu)=64,}$ $\mathrm{A_{r}(S)=32,}$ $\mathrm{A_{r}(O)=16,}$ $\mathrm{A_{r}(H)=1}$ X Y + – 400 q 20 %-li $\mathrm{CuSO_{4}}$ suda məhlulu', 'KIM-0034.png', '{"A": "32", "B": "16", "C": "64", "D": "48", "E": "8"}', 'A', '3', 'Şəkildən göründüyü kimi Y elektrodu katoddur (mənfi yüklü olduğu üçün) və elektroliz prosesi zamanı bu elektrodda $\mathrm{Cu}$ alınır. (400⋅20) : 100 = 80 q $\mathrm{CuSO_{4}}$ 80 q x q $\mathrm{2CuSO_{4} + 2H_{2}O}$ → 2Cu + $\mathrm{2H_{2}SO_{4} + O_{2}}$ 2·160 q 2·64 q 80 q $\mathrm{CuSO_{4}-------}$ x q $\mathrm{Cu}$ 2·160 q $\mathrm{CuSO_{4}----}$ 2·64 q $\mathrm{Cu}$ x = 32 q $\mathrm{Cu}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №34', 'KIM-0034_izah.png'),
  ('KIM-0035', 'Qeyri-üzvi kimya', 'Qeyri-üzvi birləşmələr arasında genetik əlaqə', 'qapali', '$\mathrm{H_{2}SO_{4}}$ (qatı) + $\mathrm{Na}$ → X +Z,t → S $\mathrm{+O^{2}}$ → , t, Z – $\mathrm{(Na_{2}SO_{4}+Y)}$ –Y X, Y və Z maddələrini müəyyən edin. X Y Z', 'KIM-0035.png', '{"A": "$\\mathrm{H_{2}S}$ $\\mathrm{SO_{2}}$ $\\mathrm{H_{2}O}$", "B": "$\\mathrm{SO_{2}}$ $\\mathrm{H_{2}O}$ $\\mathrm{H_{2}S}$", "C": "$\\mathrm{SO_{2}}$ $\\mathrm{H_{2}S}$ $\\mathrm{H_{2}O}$", "D": "$\\mathrm{H_{2}O}$ $\\mathrm{H_{2}S}$ $\\mathrm{SO_{2}}$", "E": "$\\mathrm{H_{2}S}$ $\\mathrm{H_{2}O}$ $\\mathrm{SO_{2}}$"}', 'E', '3', '$\mathrm{H_{2}SO_{4}}$ (qatı) + $\mathrm{Na \rightarrow H_{2}S + SO \rightarrow ^{2},t}$ S $\mathrm{+O^{2},}$ → t, $\mathrm{SO_{2} - (Na_{2}SO_{4}+H_{2}O) - H_{2}O}$ Sxemə əsasən X – $\mathrm{H_{2}S,}$ Y- $\mathrm{H_{2}O,}$ Z- $\mathrm{SO_{2}}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №35', 'KIM-0035_izah.png'),
  ('KIM-0036', 'Üzvi kimya', 'Spirtlər', 'qapali', 'Etil spirti və 9,2 q qliserindən ibarət qarışığın artıq miqdarda götürülmüş natriumla reaksiyasından 5,6 l (n.ş.) hidrogen alınmışdır. Qarışıqda etil spirtinin kütləsini (qram ilə) hesablayın. $\mathrm{M_{r}(C_{2}H_{5}OH)=46,}$ $\mathrm{M_{r}(C_{3}H_{5}(OH)_{3})=92}$', NULL::text, '{"A": "10,2", "B": "14,2", "C": "9,2", "D": "23,0", "E": "16,8"}', 'C', '3', '9,2 q x l $\mathrm{2C_{3}H_{5}(OH)_{3}+}$ 6Na → $\mathrm{2C_{3}H_{5}(ONa)_{3}+}$ $\mathrm{3H_{2}}$ 2·92 q 67,2 l 9,2 q qliserin--------- x l $\mathrm{H_{2}}$ 2·92q qliserin--------- 67,2 l $\mathrm{H_{2}}$ x = 3,36 l 5,6 l - 3,36 l = 2,24 l x q 2,24 $\mathrm{2C_{2}H_{5}OH}$ + 2Na → $\mathrm{2C_{2}H_{5}ONa + H_{2}}$ 2·46 22,4 x q etil spirti------------ 2,24 l $\mathrm{H_{2}}$ 2·46 q etil spirti --------- 22,4 l $\mathrm{H_{2}}$ x = 9,2 q', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №36', 'KIM-0036_izah.png'),
  ('KIM-0037', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'qapali', 'Ammonium-sulfatın hansı maddələrin suda məhlulları ilə reaksiyası axıra qədər gedir? I. Barium-xlorid II. Xlorid turşusu III. Natrium-hidroksid IV. Kalium-nitrat', NULL::text, '{"A": "I və IV", "B": "II və III", "C": "II və IV", "D": "III və IV", "E": "I və III"}', 'E', '3', 'İon mübadilə reaksiyası zəif dissosiasiya edən maddə (əsasən çöküntü, qaz, su) alınan zaman axıra qədər gedir. I. $\mathrm{(NH_{4})_{2}SO_{4} + BaCl_{2} \rightarrow BaSO_{4}}$ ↓ + $\mathrm{NH_{4}Cl}$ II. $\mathrm{(NH_{4})_{2}SO_{4} + HCl}$ → reaksiya getmir III. $\mathrm{(NH_{4})_{2}SO_{4} + NaOH \rightarrow Na_{2}SO_{4} + NH_{3}}$ ↑ + $\mathrm{H_{2}O}$ IV. $\mathrm{(NH_{4})_{2}SO_{4} + KNO_{3}}$ → reaksiya axıra qədər getmir', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №37', 'KIM-0037_izah.png'),
  ('KIM-0038', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 'X +H → $\mathrm{_{2}}$ $\mathrm{C_{2}H_{5}OH + CuO}$ → X X maddəsini müəyyən edin.', 'KIM-0038.png', '{"A": "$\\mathrm{HCOOH}$", "B": "$\\mathrm{CH_{3}}$ $\\mathrm{CH_{2}}$ C O H", "C": "$\\mathrm{CH_{3}}$ C O $\\mathrm{OH}$", "D": "$\\mathrm{CH_{3}}$ C O H", "E": "$\\mathrm{CO}$"}', 'D', '3', '$\mathrm{CH_{3}CHO + H_{2} \rightarrow CH_{3}CH_{2}OH}$ $\mathrm{CH_{3}CH_{2}OH + CuO \rightarrow CH_{3}CHO + Cu + H_{2}O}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №38', 'KIM-0038_izah.png'),
  ('KIM-0039', 'Üzvi kimya', 'Aromatik karbohidrogenlər', 'qapali', 'Benzol və toluoldan ibarət 20 q qarışığın $\mathrm{KMnO_{4}}$-ün suda məhlulu ilə oksidləşməsi zamanı üzvi maddələrdən biri tam sərf olunmuş və 12,2 q turşu alınmışdır. İlkin qarışıqda benzolun kütlə payını (%-lə) hesablayın. $\mathrm{M_{r}(C_{6}H_{6})=78,}$ $\mathrm{M_{r}(C_{7}H_{8})=92,}$ $\mathrm{M_{r}(C_{6}H_{5}COOH)=122}$', NULL::text, '{"A": "14", "B": "54", "C": "34", "D": "24", "E": "44"}', 'B', '3', 'Benzoldan fərqli olaraq toluol $\mathrm{KMnO_{4}}$-ün suda məhlulu ilə oksidləşir. x q 12,2 q $\mathrm{C_{6}H_{5}CH_{3}+3[O] \rightarrow C_{6}H_{5}COOH + H_{2}O}$ 92 q 122 q x q toluol------------ 12,2 q turşu 92 q toluol------------122 q turşu x = 9,2 q 20-9,2=10,8 (10,8:20)·100%=54%', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №39', 'KIM-0039_izah.png'),
  ('KIM-0040', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Tərkibində mürəkkəb efir qrupu olan hansı irimolekullu birləşmə polikondensləşmə reaksiyası ilə alınır?', NULL::text, '{"A": "kapron", "B": "poliizopren", "C": "fenolformaldehid qətranı", "D": "lavsan", "E": "polimetilmetakrilat"}', 'D', '3', 'Lavsan və polimetilmetakrilatın tərkibində mürəkkəb efir qrupları var. Lakin polimetilmetakrilat polimerləşmə reaksiyası ilə, lavsan isə polikondensləşmə reaksiyası ilə alınır.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №40', 'KIM-0040_izah.png'),
  ('KIM-0041', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', 'Eyni temperaturda bərabər həcmli qapalı qablarda baş verən reaksiyaların sürətlərini müqayisə edin. $\mathrm{A_{r}(N)=14,}$ $\mathrm{A_{r}(H)=1}$ 14 q $\mathrm{N_{2}}$ + 14 q $\mathrm{H_{2}}$ 14 q $\mathrm{N_{2}}$ + 14 mol $\mathrm{H_{2}}$ 14 mol $\mathrm{N_{2}}$ + 14 q $\mathrm{H_{2}}$ $\mathrm{v_{1}}$ $\mathrm{v_{2}}$ $\mathrm{v_{3}}$', 'KIM-0041.png', '{"A": "$\\mathrm{v_{1}>}$ $\\mathrm{v_{2}>}$ $\\mathrm{v_{3}}$", "B": "$\\mathrm{v_{2}>}$ $\\mathrm{v_{3}>}$ $\\mathrm{v_{1}}$", "C": "$\\mathrm{v_{3}>v_{2}>v_{1}}$", "D": "$\\mathrm{v_{1}=v_{2}=v_{3}}$", "E": "$\\mathrm{v_{3}>}$ $\\mathrm{v_{1}>}$ $\\mathrm{v_{2}}$"}', 'C', '3', 'Reaksiya eyni temperaturda və eyni həcmli qablarda baş verir. Eyni temperaturda eyni maddələr arasında baş verdiyi üçün sürət sabiti (k) dəyişmir. Kütlələrin təsiri qanununu tətbiq edərək sürətləri müqayisə edək. Qabların həcmləri bərabər olduğundan müqayisə zamanı qatılıq əvəzinə mol miqdarından istifadə edə bilərik. 14 q $\mathrm{N_{2}}$ = 0,5 mol 14 q $\mathrm{H_{2}}$ = 7 mol $\mathrm{v_{1} = k\cdot [N_{2}]\cdot [H_{2}]^{3}=}$ $\mathrm{k\cdot 0,5\cdot 7^{3}}$ $\mathrm{v_{2} = k\cdot [N_{2}]\cdot [H_{2}]^{3}=}$ $\mathrm{k\cdot 0,5\cdot 14^{3} = k\cdot 4\cdot 7^{3}}$ $\mathrm{v_{3} = k\cdot [N_{2}]\cdot [H_{2}]^{3}=}$ $\mathrm{k\cdot 14\cdot 7^{3}}$ İfadələrin müqayisəsindən aydın olur ki, $\mathrm{v_{3}>v_{2}>v_{1}}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №41', 'KIM-0041_izah.png'),
  ('KIM-0042', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Eyni mol miqdarda götürülmüş hansı metal ilə reaksiyaya daha çox xlorid turşusu sərf olunar?', NULL::text, '{"A": "$\\mathrm{Na}$", "B": "$\\mathrm{Zn}$", "C": "$\\mathrm{Al}$", "D": "$\\mathrm{Mg}$", "E": "$\\mathrm{Fe}$"}', 'C', '3', 'n valentli metalın bir molu n mol $\mathrm{HCl}$ ilə reaksiyaya daxil olur. Deməli eyni mol miqdarda götürülmüş daha yüksək valentli metal ilə reaksiyaya daha çox xlorid turşusu sərf olunar. $\mathrm{Na}$ I valentli , $\mathrm{Zn}$ və $\mathrm{Mg-II}$ valentli $\mathrm{Al}$ III valentli, $\mathrm{Fe}$ isə II, III valentlidir. Lakin $\mathrm{Fe}$ xlorid turşusu ilə $\mathrm{FeCl_{2}}$ əmələ gətirdiyindən cavab $\mathrm{Al}$ olur.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №42', 'KIM-0042_izah.png'),
  ('KIM-0046', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Maddə Qatı $\mathrm{HNO_{3}}$ ilə reaksiya məhsulu X $\mathrm{X(NO_{3})_{2}+NO_{2}+H_{2}O}$ Y $\mathrm{YO_{2}+NO_{2}+H_{2}O}$ Z $\mathrm{H_{2}ZO_{4}+NO_{2}+H_{2}O}$ X, Y və Z-i müəyyən edin. X Y Z', 'KIM-0046.png', '{"A": "$\\mathrm{Fe}$ S C", "B": "$\\mathrm{Cu}$ C S", "C": "$\\mathrm{Cu}$ P S", "D": "$\\mathrm{Cu}$ S P", "E": "$\\mathrm{Fe}$ C P"}', 'B', '3', '$\mathrm{Fe + HNO_{3} \rightarrow Fe(NO_{3})_{3}+}$ $\mathrm{NO + H_{2}O}$ $\mathrm{Cu + HNO_{3} \rightarrow Cu(NO_{3})_{2}+}$ $\mathrm{NO_{2} + H_{2}O}$ (X maddəsinə uyğun) C + $\mathrm{HNO_{3} \rightarrow CO_{2}+}$ $\mathrm{NO_{2} + H_{2}O}$ (Y maddəsinə uyğun) P + $\mathrm{HNO_{3} \rightarrow H_{3}PO_{4} + NO_{2} + H_{2}O}$ S + $\mathrm{HNO_{3} \rightarrow H_{2}SO_{4}+}$ $\mathrm{NO_{2} + H_{2}O}$ (Z maddəsinə uyğun)', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №46', 'KIM-0046_izah.png'),
  ('KIM-0048', 'Ümumi kimya', 'Atomun quruluşu və dövri sistem', 'qapali', 'Dördüncü dövrün əlavə yarımqrup elementi Atomunda elektronların ümumi sayı s p d X a+2 a+7 a X elementi üçün hansı ifadələr doğrudur? 1. ... $\mathrm{3d^{4}4s^{2}}$ qısa elektron formuluna malikdir 2. VI B qrupunda yerləşir 3. 6 cütləşməmiş (tək) elektronu var 4. Qeyri-metaldır', 'KIM-0048.png', '{"A": "2, 3", "B": "1, 3", "C": "1, 4", "D": "2, 4", "E": "1, 2"}', 'A', '3', 'Dördüncü dövrün əlavə yarımqrup elementlərinin hər birində 12 p elektronu olduğundan: a + 7 = 12 a = 5 X atomunda elektronların ümumi sayı: a+2 + a+7 + a = 24 24 protonu olan element (X). ... $\mathrm{3d^{5}4s^{1}}$ qısa elektron formuluna malikdir, 6 tək elektronu var və metaldır, VI B qrupunda yerləşir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №48', 'KIM-0048_izah.png'),
  ('KIM-0049', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'qapali', '$\mathrm{KMnO_{4}}$ → → Y $\mathrm{KClO_{3}}$ t $\mathrm{MnO_{2},}$ t + $\mathrm{HCl}$ X el-z Müəyyən şəraitdə hansı reaksiyalar baş verir? 1. X+Cu → 2. $\mathrm{Y+CO}$ → 3. X+S → 4. $\mathrm{Y+NH_{3}}$ → 5. $\mathrm{X+F_{2}}$ →', 'KIM-0049.png', '{"A": "2, 4, 5", "B": "1, 2, 5", "C": "1, 2, 3", "D": "3, 4, 5", "E": "1, 3, 4"}', 'A', '3', '$\mathrm{2KMnO_{4} \rightarrow K_{2}MnO_{4} + MnO_{2} + O_{2}}$ $\mathrm{KClO_{3}+}$ $\mathrm{6HCl \rightarrow 5KCl + 3H_{2}O + 3Cl_{2}}$ $\mathrm{2H_{2}O \rightarrow 2H_{2} + O_{2}}$ Deməli X maddəsi $\mathrm{H_{2}O,}$ Y maddəsi $\mathrm{O_{2}}$-dir. 1. $\mathrm{H_{2}O + Cu}$ → reaksiya getmir 2. $\mathrm{O_{2}+}$ $\mathrm{2CO \rightarrow 2CO_{2}}$ 3. $\mathrm{H_{2}O}$ + S → reaksiya getmir 4. $\mathrm{5O_{2}+}$ $\mathrm{4NH_{3} \rightarrow 4NO + 6H_{2}O}$ 5. $\mathrm{2H_{2}O+}$ $\mathrm{2F_{2} \rightarrow 4HF + O_{2}}$', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №49', 'KIM-0049_izah.png'),
  ('KIM-0051', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Halogenlər Nisbi atom kütləsi Atom radiusu X $\mathrm{A_{r}(X)}$ $\mathrm{r_{1}}$ Y $\mathrm{A_{r}(Y)}$ $\mathrm{r_{2}}$ Nə doğrudur?', 'KIM-0051.png', '{"A": "$\\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}=r_{2}}$", "B": "$\\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}<r_{2}}$", "C": "$\\mathrm{A_{r}(X)>A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}=r_{2}}$", "D": "$\\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}>r_{2}}$", "E": "$\\mathrm{A_{r}(X)>A_{r}(Y)}$ olarsa, $\\mathrm{r_{1}<r_{2}}$"}', 'B', '3', 'F, $\mathrm{Cl}$, $\mathrm{Br}$, I istiqamətində halogenlərin nisbi atom kütlələri və atom radiusları artır. Bu səbəbdən $\mathrm{A_{r}(X)<A_{r}(Y)}$ olarsa, $\mathrm{r_{1}<r_{2,}}$ və $\mathrm{A_{r}(X)}$ $\mathrm{>A_{r}(Y)}$ olarsa, $\mathrm{r_{1}>r_{2}}$ şərtləri ödənilir.', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №51', 'KIM-0051_izah.png'),
  ('KIM-0053', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'aciq_eded', 'Müəyyən şəraitdə hidrogen və azot arasında baş verən reaksiya zamanı reaksiyaya daxil olan və alınan qaz qarışığının ümumi mol miqdarının (ν) zamandan asılı olaraq dəyişmə qrafikinə əsasən $\mathrm{t_{1}}$ anına qədər reaksiyaya daxil olmuş hidrogenin mol sayını hesablayın. ν, mol 120 96 $\mathrm{t_{1}}$ → t, san', 'KIM-0053.png', NULL::text, '36', '3', '$\mathrm{N_{2} + 3H_{2} \rightarrow 2NH_{3}}$ Reaksiya tənliyindən göründüyü kimi 1k + 3k = 4k mol qaz qarışığı reaksiyaya girən zaman 2k mol qaz əmələ gəlir. Reaksiyaya daxil olan və alınan qaz qarışığının ümumi mol miqdarının azalması 4k – 2k = 2k mol olur. Qrafikə əsasən isə azalma 120 – 96 = 24 moldur. 2k mol azalma-----------3k mol $\mathrm{H_{2}}$ 24 mol azalma-------- x mol $\mathrm{H_{2}}$ x = 36', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №53', 'KIM-0053_izah.png'),
  ('KIM-0055', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'aciq_eded', 'Reaksiyaya daxil olan maddələr Kütləsi, q Alınan duzun formulu $\mathrm{NaOH}$ 8 $\mathrm{NaH_{2}PO_{4}}$ $\mathrm{H_{3}PO_{4}}$ x x-i hesablayın. $\mathrm{M_{r}(NaOH)=40,}$ $\mathrm{M_{r}(H_{3}PO_{4})=98}$', 'KIM-0055.png', NULL::text, '19,6', '3', '8 q x q $\mathrm{NaOH + H_{3}PO_{4} \rightarrow NaH_{2}PO_{4}+}$ $\mathrm{H_{2}O}$ 40 q 98 q 8 q $\mathrm{NaOH}$ - - - - - - x q $\mathrm{H_{3}PO_{4}}$ 40 q $\mathrm{NaOH}$ - - - - - 98 q $\mathrm{H_{3}PO_{4}}$ x = 19,6 q', '{4}', '2026', '2026-06-07 qəbul, IV qrup, A variantı №55', 'KIM-0055_izah.png'),
  ('KIM-0061', 'Üzvi kimya', 'Karbohidrogenlər (ümumi)', 'qapali', 'Tsiklopropan və propen üçün ümumi olan nədir?', NULL::text, '{"A": "quruluş formulları", "B": "molekulda siqma rabitələrin ümumi sayı", "C": "molekulda hibrid orbitalların sayı", "D": "molekulda atomlarının ümumi sayı", "E": "sənayedə alınma üsulları"}', 'D', '3', 'Həm tsiklopropan, həm də propenin kimyəvi formulu $\mathrm{C_{3}H_{6}}$-dır. Kimyəvi formuldan göründüyü kimi, molekulda atomlarının ümumi sayı eynidir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №31', 'KIM-0061_izah.png'),
  ('KIM-0062', 'Ümumi kimya', 'Kimyəvi tənliklər üzrə hesablamalar', 'qapali', '$\mathrm{CO}$ və $\mathrm{O_{2}}$-dən ibarət qaz qarışığı müəyyən şəraitdə reaksiyaya daxil olmuşdur. Qrafikə əsasən $\mathrm{\tau _{1}}$ anına qədər alınan $\mathrm{CO_{2}}$-nin həcmini (litrlə) hesablayın. 90 70 $\mathrm{\tau _{1}}$ → τ(zaman) V(l) qaz qarışığı', 'KIM-0062.png', '{"A": "40", "B": "15", "C": "20", "D": "5", "E": "10"}', 'A', '3', '$\mathrm{2CO + O_{2} \rightarrow 2CO_{2}}$ reaksiyası üzrə: Reaksiyaya daxil olan maddələrin həcmi =2+1=3 l Reaksiyadan alınan $\mathrm{CO_{2}}$ həcmi = 2 l Fərq = 3-2 = 1 litr Reaksiya tənliyi üzrə 1 litr fərq------2 litr $\mathrm{CO_{2}}$ 20 litr fərq-------x litr CO2/ alınır x = 40 litr', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №32', 'KIM-0062_izah.png'),
  ('KIM-0063', 'Ümumi kimya', 'Atomun quruluşu və dövri sistem', 'qapali', '$\mathrm{X^{3+}}$ ionundakı elektronların sayı azot atomunun $\mathrm{(_{7}N)}$ xarici elektron təbəqəsində olan elektronların sayından 2 dəfə çoxdursa, X atomunun dövri sistemdə mövqeyini müəyyən edin. Dövr Qrup Yarımqrup', 'KIM-0063.png', '{"A": "IV VI əlavə", "B": "III VII əsas", "C": "IV II əsas", "D": "III III əsas", "E": "III II əlavə"}', 'D', '3', 'Azot atomunun elektron formulu $\mathrm{_{7}N}$ .... $\mathrm{1s^{2}/2s^{2}}$ $\mathrm{2p^{3}.}$ Göründüyü kimi, azot atomunun xarici elektron təbəqəsində 5 elektron var. Onda $\mathrm{X^{3+}}$ ionunda 10 elektron var. Deməli, neytral X atomunda 13 elektron var. X atomunun elektron formulundan $\mathrm{(_{13}X}$ $\mathrm{1s^{2}/2s^{2}}$ $\mathrm{2p^{6}/3s^{2}}$ $\mathrm{3p^{1})}$ aydın olur ki, o dövri sistemdə III dövr, III qrupun əsas yarımqrupunda yerləşir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №33', 'KIM-0063_izah.png'),
  ('KIM-0064', 'Üzvi kimya', 'Alkanlar', 'qapali', '1 mol $\mathrm{C_{n}H_{2n+2}}$ alkanının xlor ilə reaksiyası zamanı hidrogen atomlarının ümumi sayının 60%-i əvəz olunur və 219 q $\mathrm{HCl}$ əmələ gəlir. n-i hesablayın. $\mathrm{M_{r}(HCl)=36,5}$', NULL::text, '{"A": "4", "B": "3", "C": "2", "D": "5", "E": "6"}', 'A', '3', 'Alkanlar xlorla əvəzetmə reaksiyasına daxil olur. Bu reaksiyalar zamanı neçə mol hidrogen atomu əvəzlənirsə, həmin miqdarda (mol) $\mathrm{HCl}$ alınır. Əmələ gələn $\mathrm{HCl}$-un miqdarı 219/36,5 =6 moldur. Əgər hidrogen atomlarının 60% faizi əvəz olunubsa, deməli alkan molekulunda 10 hidrogen atomu var. Molekulunda 10 hidrogen atomu olan alkan $\mathrm{C_{4}H_{10}}$-dur. (2n+2=10, n=4)', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №34', 'KIM-0064_izah.png'),
  ('KIM-0068', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', 'Müəyyən miqdar metanın tam yanmasına 6 mol oksigen sərf edilmiş və 2640 kC istilik ayrılmışdır. Reaksiyanın istilik effektini (kC ilə) hesablayın.', NULL::text, '{"A": "1760", "B": "440", "C": "220", "D": "3520", "E": "880"}', 'E', '3', 'Metanın yanma reaksiyasının tənliyinə əsasən 6 mol 2640 kC ayrılır $\mathrm{CH_{4}+}$ $\mathrm{2O_{2} \rightarrow CO_{2} + 2H_{2}O}$ +Q kC 2 mol Q kC ayrılır Q=880 kC', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №38', 'KIM-0068_izah.png'),
  ('KIM-0069', 'Üzvi kimya', 'Mürəkkəb efirlər', 'qapali', 'Efirləşmə reaksiyasına daxil olan maddələr Molekulunda karbon atomlarının sayı Alınan mürəkkəb efir molekulunda siqma rabitələrin ümumi sayı Doymuş biratomlu spirt n x Doymuş birəsaslı karbon turşusu 2n x-i hesablayın.', 'KIM-0069.png', '{"A": "9n – 1", "B": "9n + 1", "C": "9n + 5", "D": "9n + 3", "E": "9n"}', 'B', '3', 'Efirləşmə reaksiyasından alınan mürəkkəb efir molekulunda karbon atomlarının ümumi sayı efiri əmələ gətirən spirt və karbon turşusunun molekulunda karbon atomlarının cəminə bərabərdir. Mürəkkəb efirlərin ümumi formulu $\mathrm{C_{y}H_{2y}O_{2}}$ olduğundan y=n+2n=3n karbon atomu olan mürəkkəb efirin formulunu $\mathrm{C_{3n}H_{6n}O_{2}}$ kimi göstərə bilərik. Mürəkkəb efir molekulunda siqma rabitələrin sayını hesabladıqda σ=3n+6n+2-1= 9n+1 alınır', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №39', 'KIM-0069_izah.png'),
  ('KIM-0070', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Halogenlər Kütləsi, q Halogenlə reaksiyaya sərf olunan natriumun kütləsi, q $\mathrm{X_{2}}$ a $\mathrm{m_{1}}$ $\mathrm{Y_{2}}$ a $\mathrm{m_{2}}$ $\mathrm{Z_{2}}$ a $\mathrm{m_{3}}$ $\mathrm{m_{2}>m_{3}>m_{1}}$ olarsa, halogenlərin reduksiyaedicilik qabiliyyətinin artma sırasını müəyyən edin (halogenlər reaksiyaya tam sərf olunur).', 'KIM-0070.png', '{"A": "$\\mathrm{Y_{2},}$ $\\mathrm{X_{2},}$ $\\mathrm{Z_{2}}$", "B": "$\\mathrm{Z_{2},}$ $\\mathrm{X_{2},}$ $\\mathrm{Y_{2}}$", "C": "$\\mathrm{Y_{2},}$ $\\mathrm{Z_{2},}$ $\\mathrm{X_{2}}$", "D": "$\\mathrm{X_{2},}$ $\\mathrm{Z_{2},}$ $\\mathrm{Y_{2}}$", "E": "$\\mathrm{X_{2},}$ $\\mathrm{Y_{2},}$ $\\mathrm{Z_{2}}$"}', 'C', '3', 'Dövri sistemdə halogenlərin qrup daxilində yuxarıdan aşağı getdikcə əmələ gətirdiyi bəsit maddələrin molyar kütləsi artdıqca onların reduksiyaedicilik qabiliyyəti artır. Ümumi şəkildə eyni kütlədə götürülmüş halogenlərin $\mathrm{Na}$ ilə reaksiyasına sərf olunan natriumun kütləsini aşağıdakı sxem üzrə hesablamaq olar: a m $\mathrm{Hlg_{2}}$ +2Na → 2NaHlg 46 = a m M M 46 Hesablamadan göründüyü kimi, molyar kütləsi az olan halogenlə reaksiyaya daha çox natrium sərf olunur.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №40', 'KIM-0070_izah.png'),
  ('KIM-0071', 'Ümumi kimya', 'Elektroliz', 'qapali', 'Duzun suda məhlulu Elektroliz zamanı katodda anodda elektrolit məhlulunda alınan birəsaslı turşunun mol sayı yalnız metal ayrılır ayrılan qazın həcmi (l, n.ş.) 11,2 x x-i hesablayın.', 'KIM-0071.png', '{"A": "1", "B": "0,5", "C": "2", "D": "4", "E": "1,5"}', 'C', '3', 'Cədvəldəki məlumatlara əsasən, elektrolizin ümumi tənliyini aşağıdakı kimi yazmaq olar: $\mathrm{4MeX_{n} + 2nH_{2}O}$ → 4Me + $\mathrm{nO_{2}}$ +4nHX 11,2 litr $\mathrm{O_{2}---------------a}$ mol HX n⋅22,4 litr $\mathrm{O_{2}---------}$ 4n mol HX a= 2 mol', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №41', 'KIM-0071_izah.png'),
  ('KIM-0072', 'Üzvi kimya', 'Spirtlər', 'qapali', '$\mathrm{+CH_{3}COOH,}$ t, H → $\mathrm{_{2}SO_{4}(q)}$ X $\mathrm{CH_{3}OH + HCl}$, t, $\mathrm{H_{2} \rightarrow SO_{4}}$ (q) Y – $\mathrm{H_{2}O - H_{2}O}$ X və Y maddələrini müəyyən edin. X Y', 'KIM-0072.png', '{"A": "$\\mathrm{CH_{4}}$ $\\mathrm{CH_{3}OCl}$", "B": "$\\mathrm{HCOOCH_{3}}$ $\\mathrm{CH_{3}Cl}$", "C": "$\\mathrm{CH_{3}COOCH_{3}}$ $\\mathrm{CH_{3}Cl}$", "D": "$\\mathrm{CH_{3}COOCH_{3}}$ $\\mathrm{CH_{3}OCl}$", "E": "$\\mathrm{CH_{4}}$ $\\mathrm{CH_{3}Cl}$"}', 'C', '3', '$\mathrm{CH_{3}OH + CH_{3}COOH}$ $\mathrm{CH \rightarrow _{3}COOCH_{3}+}$ $\mathrm{H_{2}O}$ $\mathrm{H_{2}SO_{4}(q),}$ t $\mathrm{CH_{3}OH + HCl}$ $\mathrm{CH \rightarrow _{3}Cl + H_{2}O}$ $\mathrm{H_{2}SO_{4}(q),t}$ Reaksiyalara əsasən X - $\mathrm{CH_{3}COOCH_{3,}Y}$ isə $\mathrm{CH_{3}Cl}$ maddəsidir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №42', 'KIM-0072_izah.png'),
  ('KIM-0073', 'Üzvi kimya', 'Aromatik karbohidrogenlər', 'qapali', 'Maddə Aqreqat halı $\mathrm{HNO_{3}}$ ilə reaksiya tipi Bir molekulunda atomların sayı X maye əvəzetmə 12 X maddəsini müəyyən edin.', 'KIM-0073.png', '{"A": "toluol", "B": "benzol", "C": "fenol", "D": "anilin", "E": "propen"}', 'B', '3', 'Toluol $\mathrm{(C_{7}H_{8})}$ molekulunda 15 atom var və mayedir. Benzol $\mathrm{(C_{6}H_{6})}$ molekulunda 12 atom var və mayedir, $\mathrm{HNO_{3}}$ ilə reaksiyanın tipi- əvəzetmə Fenol $\mathrm{(C_{6}H_{5}OH)}$ molekulunda 13 atom var və bərkdir. Anilin $\mathrm{(C_{6}H_{5}NH_{2})}$ molekulunda 14 atom var və mayedir. Propen $\mathrm{(C_{3}H_{6})}$ molekulunda 9 atom var və qazdır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №43', 'KIM-0073_izah.png'),
  ('KIM-0074', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', '$\mathrm{N_{2}+}$ $\mathrm{3H_{2} \Leftrightarrow 2NH_{3}+}$ Q reaksiyasında temperatur və təzyiqi necə dəyişmək lazımdır ki, tarazlıq ilkin maddələrin alınması istiqamətinə yerini dəyişsin? Temperatur Təzyiq', 'KIM-0074.png', '{"A": "artırmaq artırmaq", "B": "azaltmaq artırmaq", "C": "azaltmaq azaltmaq", "D": "dəyişməmək artırmaq", "E": "artırmaq azaltmaq"}', 'E', '3', 'Le-Şatelye prinsipinə görə tarazlıqda olan sistemə xaricdən təsir edildikdə kimyəvi tarazlıq sistemdə həmin təsirin azaldığı tərəfə yönəlir. Verilmiş dönən reaksiyada sola gedən reaksiya endotermikdir və sistemdə təzyiqin artması ilə baş verir. Bunlara əsasən , $\mathrm{N_{2}+}$ $\mathrm{3H_{2} \Leftrightarrow 2NH_{3}+}$ Q reaksiyasında tarazlığı ilkin maddələrin alınması istiqamətinə yönəltmək üçün temperaturu artırmaq, təzyiqi azaltmaq lazımdır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №44', 'KIM-0074_izah.png'),
  ('KIM-0079', 'Üzvi kimya', 'Aminlər və aminturşular', 'qapali', 'O H $\mathrm{H_{2}N}$ $\mathrm{CH}$ C N $\mathrm{CH}$ C $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$ O $\mathrm{OH}$ Maddə üçün doğru ifadələr: 1. Qlisinin dipeptididir 2. α-alaninin dipeptididir 3. 1 molunun tam hidrolizinə 2 mol su sərf olunur 4. 1 molunun tam hidrolizindən 2 mol aminturşu əmələ → gəlir 5. Molekulunda 1 peptid rabitə var', 'KIM-0079.png', '{"A": "1, 3, 5", "B": "1, 2, 3", "C": "2, 3, 4", "D": "1, 3, 4", "E": "2, 4, 5"}', 'E', '3', 'Qeyd edilən maddə α-alaninin dipeptididir. Dipeptid molekulunda 1 peptid rabitəsi olur, bir molunun hidrolizi zamanı 1 mol su sərf olunur və 2 mol aminturşu əmələ gəlir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №49', 'KIM-0079_izah.png'),
  ('KIM-0080', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', '0,2 mol $\mathrm{H_{2}S}$ 0,6 mol oksigen ilə $\mathrm{2H_{2}S + 3O_{2}t \rightarrow 2H_{2}O + 2SO_{2}}$ reaksiyasına tam daxil olur. Hansı ifadələr doğrudur? $\mathrm{M_{r}(H_{2}O)=18}$ I. 0,2 mol $\mathrm{SO_{2}}$ alınır II. 7,2 q $\mathrm{H_{2}O}$ alınır III. 0,3 mol $\mathrm{O_{2}}$ artıq qalır', NULL::text, '{"A": "II, III", "B": "I, III", "C": "yalnız I", "D": "I, II", "E": "yalnız III"}', 'B', '3', 'verilən: 0,2 mol 0,6 mol sərf olunan: 0,2 mol 0,3 mol x q y mol $\mathrm{2H_{2}S + 3O_{2}t \rightarrow 2H_{2}O + 2SO_{2}}$ 2 mol 3 mol 36 q 2 mol Verilmiş mol miqdarlarından aydındır ki, reaksiya zamanı $\mathrm{H_{2}S}$ tam sərf olunur. X=3,6 q $\mathrm{H_{2}O}$ ,Y =0,2 mol $\mathrm{SO_{2}}$ alınır . 0,3 mol $\mathrm{O_{2}}$ artıq qalır.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №50', 'KIM-0080_izah.png'),
  ('KIM-0081', 'Üzvi kimya', 'Karbohidratlar', 'qapali', 'm sayda asimmetrik karbon atomu olan sellülozanın tam yanmasından neçə mol karbon-dioksid alınar?', NULL::text, '{"A": "6m", "B": "1,5m", "C": "5m", "D": "3m", "E": "1,2m"}', 'E', '3', 'Sellülozanın makromolekulunda karbon atomlarının ümumi sayı 6n, asimmetrik karbon atomlarının sayı 5n-dir. Tənasüb qursaq: 5n -------------- 6n mol $\mathrm{CO_{2}}$ m------------------x mol $\mathrm{CO_{2}}$ x = 1,2m', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №51', 'KIM-0081_izah.png'),
  ('KIM-0082', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'qapali', '$\mathrm{Si}$ $\mathrm{+X+H_{2}O}$ Y + $\mathrm{HCl}$ → Z – $\mathrm{H_{2} - NaCl}$ Z maddəsini müəyyən edin.', NULL::text, '{"A": "$\\mathrm{SiO_{2}}$", "B": "$\\mathrm{H_{2}SiO_{3}}$", "C": "$\\mathrm{SiH_{4}}$", "D": "$\\mathrm{H_{2}O}$", "E": "$\\mathrm{SiO}$"}', 'B', '3', 'Sxemdən göründüyü kimi, X - $\mathrm{NaOH}$, Y - $\mathrm{Na_{2}SiO_{3}-}$ dür. $\mathrm{Na_{2}SiO_{3} + 2HCl \rightarrow 2NaCl + H_{2}SiO_{3}(Z)}$', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №52', 'KIM-0082_izah.png'),
  ('KIM-0083', 'Qeyri-üzvi kimya', 'Metallar', 'aciq_eded', '4,6 q natriumun artıq miqdarda su ilə qarşılıqlı təsirindən ayrılan miqdarda hidrogen almaq üçün neçə qram dəmirə xlorid turşusu ilə təsir etmək lazımdır? $\mathrm{A_{r}(Fe)=56,}$ $\mathrm{A_{r}(Na)=23}$', NULL::text, NULL::text, '5,6', '3', '4,6 x 2Na + $\mathrm{2H_{2}O \rightarrow 2NaOH + H_{2}}$ 46 1 mol x=0,1 mol y 0,1 $\mathrm{Fe + 2HCl \rightarrow FeCl_{2} + H_{2}}$ 56 1 mol y = 5,6', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №53', 'KIM-0083_izah.png'),
  ('KIM-0084', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'aciq_eded', '3,3-dimetilbutanal molekulunda funksional qrupun kütlə payını (%-lə) hesablayın. $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '29', '3', '3,3-dimetilbutanalın kimyəvi formulu $\mathrm{C_{6}H_{12}O,}$ 1 molunun kütləsi 100 qramdır. Tərkibində olan $\mathrm{CHO}$ funksional qrupunun kütləsinin 29 qram olduğunu nəzərə alsaq, bu funksional qrupun kütlə payı 29% təşkil edir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №54', 'KIM-0084_izah.png'),
  ('KIM-0085', 'Ümumi kimya', 'Məhlullar', 'aciq_eded', 'Doymamış duz məhlulunun qatılığının (%) məhlulun kütləsindən (q) asılılıq qrafikinə əsasən doğru olmayan ifadələri müəyyən edin. c b a $\mathrm{m_{1}}$ m → $\mathrm{_{2}}$ mməh ω, % $\mathrm{X_{2}}$ $\mathrm{X_{1}}$ $\mathrm{X_{3}}$ 1. $\mathrm{X_{1} \rightarrow X_{2}}$ keçidi üçün məhlula yalnız duz əlavə olunur 2. $\mathrm{X_{1} \rightarrow X_{3}}$ keçidi üçün məhlula yalnız duz əlavə olunur 3. $\mathrm{X_{3} \rightarrow X_{1}}$ keçidi üçün məhluldan su buxarlanır 4. $\mathrm{X_{2} \rightarrow X_{1}}$ keçidi üçün məhlula su əlavə olunur', 'KIM-0085.png', NULL::text, '2,4', '3', '$\mathrm{1.X_{1} \rightarrow X_{2}}$ keçidi zamanı məhlulun qatılığı və kütləsi artmışdır. Deməli, məhlula duz əlavə olunub 2. $\mathrm{X_{1} \rightarrow X_{3}}$ keçidi zamanı məhlulun qatılığı azalır, kütləsi artır. Deməli, məhlula su əlavə olunub və ya həmin duzun fərqli qatılıqda məhlulu əlavə olunub. $\mathrm{3.X_{3} \rightarrow X_{1}}$ keçidi zamanı məhlulun qatılığı artır, kütləsi azalır. Deməli məhluldan su buxarlanır $\mathrm{4.X_{2} \rightarrow X_{1}}$ keçidi zamanı məhlula su əlavə olunsa idi , məhlulun kütləsi artacaqdır', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №55', 'KIM-0085_izah.png'),
  ('KIM-0086', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'aciq_eded', 'Termiki parçalanmaya davamlı 25% kənar qarışıq saxlayan əhəngdaşının tərkibindəki $\mathrm{CaCO_{3}}$-ün tam parçalanmasından 134 qram bərk qalıq alınmışdır. Parçalanma zamanı alınan karbon qazının həcmini (litr, n.ş.) hesablayın. $\mathrm{A_{r}(Ca)=40,}$ $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '33,6', '3', 'Əhəng daşının kütləsini x qram götürüb, hesablamaları aparaq 0,75x a $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO + CO_{2}}$ 100 56 a= 0,42x q $\mathrm{CaO}$ 0,25x + 0,42x =134 x=200 0,75⋅200 b $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO + CO_{2}}$ 100 22,4 b =33,6', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №56', 'KIM-0086_izah.png'),
  ('KIM-0091', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Qarışıq Ayrılma üsulu etanol + su X X-i müəyyən edin.', 'KIM-0091.png', '{"A": "durultma", "B": "süzmə", "C": "kristallaşdırma", "D": "distillə", "E": "xromatoqrafiya"}', 'D', '3', 'Etanol suda həll olan mayedir və su ilə eynicinsli qarışıq əmələ gətirir. Məlumdur ki, bir birində həll olan maye maddələri bir-birindən ayırmaq üçün distillə üsulundan istifadə olunur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №61', 'KIM-0091_izah.png'),
  ('KIM-0092', 'Ümumi kimya', 'Oksidləşmə-reduksiya reaksiyaları', 'qapali', '$\mathrm{KOH + Cl_{2}}$ t → $\mathrm{KCl + KClO_{3}+}$ $\mathrm{H_{2}O}$ reaksiyası üçün nə doğrudur? 1. $\mathrm{Cl_{2}}$ həm oksidləşdirici, həm də reduksiyaedicidir 2. $\mathrm{KCl}$ oksidləşmə məhsuludur 3. $\mathrm{KClO_{3}}$ reduksiyaedicidir', NULL::text, '{"A": "1, 3", "B": "yalnız 3", "C": "yalnız 2", "D": "yalnız 1", "E": "1, 2"}', 'D', '3', '$\mathrm{KOH + Cl_{2}}$ t → $\mathrm{KCl + KClO_{3} + H_{2}O}$ 0 -1 +5 Oksidləşmə dərəcəsinin dəyişməsinə görə $\mathrm{Cl_{2}}$ həm oksidləşdirici, həm də reduksiyaedicidir, $\mathrm{KCl}$ reduksiya məhsuludur, $\mathrm{KClO_{3}}$ oksidləşmə məhsuludur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №62', 'KIM-0092_izah.png'),
  ('KIM-0093', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'qapali', 'Hansı reaksiya nəticəsində alınan maddələrin hər ikisi natrium-hidroksid məhlulu ilə reaksiyaya daxil olur?', NULL::text, '{"A": "$\\mathrm{NH_{3} + O_{2}}$ t →", "B": "$\\mathrm{CaCO_{3}}$ t →", "C": "$\\mathrm{Mg(OH)_{2}}$ t →", "D": "$\\mathrm{H_{2}S + O_{2}}$ t →", "E": "$\\mathrm{FeS_{2} + O_{2}}$ t →"}', 'E', '3', 'A) $\mathrm{FeS_{2} + O_{2}}$ t → $\mathrm{Fe_{2}O_{3}+SO_{2}}$ B) $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO}$ $\mathrm{+CO_{2}}$ C) $\mathrm{NH_{3} + O_{2}}$ t → $\mathrm{N_{2}}$ $\mathrm{+H_{2}O}$ D) $\mathrm{H_{2}S + O_{2}}$ t → $\mathrm{SO_{2}}$ $\mathrm{+H_{2}O}$ E) $\mathrm{Mg(OH)_{2}}$ t → $\mathrm{MgO}$ $\mathrm{+H_{2}O}$ Verilən reaksiya sxemlərində göründüyü kimi $\mathrm{FeS_{2} + O_{2}}$ t → $\mathrm{Fe_{2}O_{3}+SO_{2}}$ reaksiyasından alınan $\mathrm{Fe_{2}O_{3}}$ amfoter , $\mathrm{SO_{2}}$ isə turşu oksididir. Bu maddələrin ikisi $\mathrm{NaOH}$ məhlulu ilə reaksiyaya daxil olur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №63', 'KIM-0093_izah.png'),
  ('KIM-0094', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'qapali', 'Y-in suda məhlulu X $\mathrm{CO_{2}}$ X və Y maddələrini müəyyən edin. X Y', 'KIM-0094.png', '{"A": "$\\mathrm{NaCl}$ $\\mathrm{CaCO_{3}}$", "B": "$\\mathrm{KNO_{3}}$ $\\mathrm{Na_{2}CO_{3}}$", "C": "$\\mathrm{HCl}$ $\\mathrm{K_{2}CO_{3}}$", "D": "$\\mathrm{CaCO_{3}}$ $\\mathrm{K_{2}CO_{3}}$", "E": "$\\mathrm{K_{2}CO_{3}}$ $\\mathrm{CaCO_{3}}$"}', 'C', '3', 'Şərtə əsasən yalnız $\mathrm{K_{2}CO_{3}+2HCl \rightarrow KCl}$ $\mathrm{+CO_{2}}$ $\mathrm{+H_{2}O}$ reaksiyasında $\mathrm{CO_{2}}$ alınır.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №64', 'KIM-0094_izah.png'),
  ('KIM-0095', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'm (Me), q 12 zaman → → 2,2 ν $\mathrm{(H_{2}),}$ mol 0,7 zaman Qələvi metalın xlorid turşusu ilə reaksiyasının qrafiklərinə əsasən metalın nisbi atom kütləsini hesablayın.', 'KIM-0095.png', '{"A": "39", "B": "24", "C": "1", "D": "23", "E": "7"}', 'E', '3', 'Qələvi metalların xlorid turşusu ilə reaksiyasını ümumi şəkildə 2Me+2HCl → 2MeCl + $\mathrm{H_{2}}$ tənliyi ilə ifadə edə bilərik. Tənliyə əsasən hesablama aparsaq $\mathrm{2A_{r}(Me)------------1}$ mol $\mathrm{H_{2}}$ 9,8 q Me-------0,7 mol $\mathrm{H_{2}}$ $\mathrm{A_{r}(Me)}$ =7. Metalın nisbi atom kütləsi 7-dir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №65', 'KIM-0095_izah.png'),
  ('KIM-0097', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Polikondensləşmə reaksiyası tənliyinin sxemini göstərin.', 'KIM-0097.png', '{"A": "$\\mathrm{OH}$ + nH C H → O n t, $\\mathrm{H^{+}}$", "B": "$\\mathrm{HOOC}$ $\\mathrm{COOH+CH_{3}CH_{2}OH}$ → t, $\\mathrm{H^{+}}$", "C": "$\\mathrm{CH_{3}COOH + HOCH_{2}CH_{2}OH}$ t, H → $\\mathrm{^{+}}$", "D": "$\\mathrm{nCH_{2}}$ $\\mathrm{CHCl}$ → t, p, kat", "E": "$\\mathrm{CH}$ $\\mathrm{CH_{2} + nCH_{2}}$ $\\mathrm{CH}$ $\\mathrm{CH}$ $\\mathrm{CH_{2}}$ → n t, p, kat"}', 'A', '3', '$\mathrm{OH}$ + nH C H → O n t, $\mathrm{H^{+}}$ reaksiyası üzrə fenol və formaldehid birlikdə polikondensləşərək polimerlərə aid olan fenolformaldehid qatranı və su əmələ gətirir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №67', 'KIM-0097_izah.png'),
  ('KIM-0098', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'qapali', 'I. $\mathrm{CH_{3}COOH}$ və $\mathrm{NaOH}$ II. $\mathrm{Ba(OH)_{2},}$ $\mathrm{HCl}$ və $\mathrm{HNO_{3}}$ III. $\mathrm{HCl}$ və $\mathrm{KOH}$ Eyni həcmli və eyni molyar qatılıqlı verilmiş maddələrin məhlullarının qarışıqlarının hansılarında mühit neytraldır?', NULL::text, '{"A": "yalnız I", "B": "yalnız III", "C": "yalnız II", "D": "I, II, III", "E": "II, III"}', 'E', '3', 'I. $\mathrm{CH_{3}COOH + NaOH \rightarrow H_{2}O + CH_{3}COONa}$ (mühit qələvi) II $\mathrm{Ba(OH)_{2} + HCl + HNO_{3} \rightarrow BaCl(NO_{3}) + H_{2}O}$ (mühit neytral) III. $\mathrm{HCl + KOH \rightarrow KCl+H_{2}O}$ (mühit neytral)', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №68', 'KIM-0098_izah.png'),
  ('KIM-0099', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', '$\mathrm{2H_{2}(q)+O_{2}(q)=2H_{2}O(m)+572}$ kC Termokimyəvi tənliyi üçün hansı ifadələr doğrudur? 1. Suyun əmələgəlmə istiliyi +286 kC/mol-dur 2. Reaksiyanın istilik effekti +286 kC-dur 3. Hidrogenin yanma istiliyi +286 kC/mol-dur 4. Suyun parçalanma reaksiyasının istilik effekti +572 kC-dur', NULL::text, '{"A": "2, 4", "B": "1, 3", "C": "2, 3", "D": "3, 4", "E": "1, 2, 3"}', 'B', '3', 'Verilmiş termokimyəvi tənliyə uyğun olaraq 1. Suyun əmələgəlmə istiliyi 572:2= +286 kC/mol-dur 2. Reaksiyanın istilik effekti 572 kC-dur 3. Hidrogenin yanma istiliyi 572:2= +286 kC/mol-dur 4. Suyun parçalanma reaksiyasının istilik effekti - 572 kC-dur', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №69', 'KIM-0099_izah.png'),
  ('KIM-0100', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', '$\mathrm{Fe_{2}(SO_{4})_{3}}$ t → $\mathrm{Fe_{2}O_{3}+X}$ Hansı ifadə doğrudur?', NULL::text, '{"A": "reaksiya oksidləşmə-reduksiya reaksiyasıdır", "B": "X – $\\mathrm{SO_{2}}$-dir", "C": "X – sulfat turşusudur", "D": "kükürd atomu reduksiyaedicidir", "E": "X qələvilərlə reaksiyaya daxil olur"}', 'E', '3', 'Dəmir(III)sulfatın parçalanma reaksiyası: $\mathrm{Fe_{2}(SO_{4})_{3}}$ t → $\mathrm{Fe_{2}O_{3}+}$ $\mathrm{SO_{3}}$ kimidir. Reaksiya tənliyindən aydın olur ki, X maddəsi $\mathrm{SO_{3}}$-dür. $\mathrm{SO_{3}}$ turşu oksidi olduğu üçün qələvilərlə reaksiyaya daxil olur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №70', 'KIM-0100_izah.png'),
  ('KIM-0101', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'qapali', '$\mathrm{X_{2}}$ $\mathrm{Fe}$ $\mathrm{HCl}$ $\mathrm{KMnO_{4}}$ $\mathrm{Y_{2}}$ $\mathrm{H_{2}O}$ 7 mol $\mathrm{X_{2}}$ və 3 mol $\mathrm{Y_{2}}$ tam reaksiyaya daxil olarsa, ilkin maddələrin birindən neçə mol artıq qalar?', 'KIM-0101.png', '{"A": "1", "B": "4", "C": "2", "D": "5", "E": "3"}', 'A', '3', '$\mathrm{Fe + 2HCl \rightarrow FeCl_{2}+}$ $\mathrm{H_{2}}$ $\mathrm{(X_{2})}$ 2 $\mathrm{KMnO_{4}t \rightarrow K_{2}MnO_{4} + MnO_{2}+}$ $\mathrm{O_{2}(Y_{2})}$ 6 3 $\mathrm{2H_{2} + O_{2} \rightarrow 2H_{2}O}$ 2 1 Tənliyə əsasən 7 mol $\mathrm{H_{2}}$ və 3 mol $\mathrm{O_{2}}$ tam reaksiyaya daxil olduqda, oksigenin hamısı sərf olunur və 1 mol $\mathrm{H_{2}(7-6=1)}$ artıq qalır', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №71', 'KIM-0101_izah.png'),
  ('KIM-0102', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 't, kat → $\mathrm{CH_{3}}$ C O H $\mathrm{+H_{2}}$ X X-i müəyyən edin.', 'KIM-0102.png', '{"A": "etil spirti", "B": "dietil efiri", "C": "asetaldehid", "D": "sirkə turşusu", "E": "metil spirti"}', 'A', '3', 'Aldehidlərin hidrogenlə reaksiyasından molekulunda eyni sayda karbon atomu olan birli spirtlər alınır. t, kat → $\mathrm{CH_{3}}$ C O H $\mathrm{+H_{2}}$ reaksiyasından etil spirtinin $\mathrm{(C_{2}H_{5}OH)}$ alındığı məlum olur. $\mathrm{X=C_{2}H_{5}OH,}$ etil spirti.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №72', 'KIM-0102_izah.png'),
  ('KIM-0103', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 'Maddə Homoloji sırada yeri Molekulunda karbon atomlarının sayı Doymuş alifatik keton 3 x x-i müəyyən edin.', 'KIM-0103.png', '{"A": "7", "B": "5", "C": "4", "D": "6", "E": "3"}', 'B', '3', 'Ketonlar $\mathrm{C_{n}H_{2n}O}$ ümumi formuluna malikdir. Doymuş alifatik ketonların homoloji sırasının birinci nümayəndəsinin molekulunda 3 karbon atomu var. Deməli, homoloji sıranın üçüncü nümayəndəsinin molekulunda 5 karbon atomu olacaq.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №73', 'KIM-0103_izah.png'),
  ('KIM-0106', 'Ümumi kimya', 'Məhlullar', 'qapali', '20%-li doymamış məhlul hazırlamaq üçün 40 q duzu neçə qram suda həll etmək lazımdır?', NULL::text, '{"A": "210", "B": "160", "C": "120", "D": "80", "E": "100"}', 'B', '3', 'Məsələnin şərtinə əsasən 40 q duz suda həll edildikdə 20% məhlul alınmışdır. Deməli bu məhlulun kütləcə 20 % duz 80 % isə sudur. Uyğun hesablama aparsaq 20%---------------40 q 80%-----------------x q x=160', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №76', 'KIM-0106_izah.png'),
  ('KIM-0108', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Reaksiyaya daxil olan maddələr Həcmi, (l, n.ş.) Alınan karbamidin kütləsi, q $\mathrm{CO_{2}}$ 22,4 15 $\mathrm{NH_{3}}$ x İlkin maddələrdən biri tam reaksiyaya daxil olarsa, x-i hesablayın. $\mathrm{M_{r}((NH_{2})_{2}CO)=60}$', 'KIM-0108.png', '{"A": "28", "B": "33,6", "C": "11,2", "D": "24", "E": "44,8"}', 'C', '3', '44,8 litr 22,4 litr 60 2 $\mathrm{NH_{3} + CO_{2} \rightarrow CO(NH_{2})_{2}}$ $\mathrm{+H_{2}O}$ x litr 22,4 litr 15 verilən $\mathrm{CO_{2}}$ qaz artıq miqdarda götürülüb. Göründüyü kimi, 22,4 litr $\mathrm{CO_{2}}$-dən reaksiyaya 4 dəfə az, yəni 5,6 litr qaz daxil olur. 44,8 litr ------ 60 q CO(N $\mathrm{H_{2})_{2}}$ x litr -------- 15 q CO(N $\mathrm{H_{2})_{2}}$ / x=11,2 litr (n.ş) $\mathrm{NH_{3}}$ tam reaksiyaya daxil olur', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №78', 'KIM-0108_izah.png'),
  ('KIM-0110', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Mürəkkəb efirlərə aid olan irimolekullu birləşməni göstərin.', NULL::text, '{"A": "sellüloza", "B": "kapron", "C": "təbii kauçuk", "D": "lavsan", "E": "polivinilxlorid"}', 'D', '3', 'Verilmiş iri molekullu birləşmələrdən yalnız lavsan efirləşmə reaksiyasından alınır. Lavsan makromolekulunda mürəkkəb efir qrupu var. Deməli, lavsan mürəkkəb efirlərə aid olan iri molekullu birləşmədir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №80', 'KIM-0110_izah.png'),
  ('KIM-0111', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', '$\mathrm{C_{n}H_{2n-2}}$ $\mathrm{+2H_{2},}$ t, kat. → X X molekulunda atomların ümumi sayını hesablayın.', NULL::text, '{"A": "2n+2", "B": "3n", "C": "3n+2", "D": "3n–2", "E": "2n–2"}', 'C', '3', '$\mathrm{C_{n}H_{2n-2}}$ $\mathrm{+2H_{2},}$ t, kat. → CnH2n+2 X $\mathrm{-C_{n}H_{2n+2}}$ tərkibli karbohidrogendir. Onun molekulunda atomların ümumi sayı ( n+2n+2 =3n+2) 3n+2 cəmindən ibarətdir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №81', 'KIM-0111_izah.png'),
  ('KIM-0112', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', 'Temperaturun artması ilə reaksiyanın getmə müddəti 3 dəfə azalarsa, kimyəvi reaksiyanın sürəti necə dəyişər?', NULL::text, '{"A": "dəyişməz", "B": "3 dəfə azalar", "C": "3 dəfə artar", "D": "9 dəfə artar", "E": "9 dəfə azalar"}', 'C', '3', 'Bildiyimiz kimi, $\mathrm{\upsilon _{t2/}\upsilon _{t1=}\tau _{1/}\tau _{2}}$ Buna görə, reaksiyanın sürəti getmə müddəti 3 dəfə azalarsa, sürəti 3 dəfə artar', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №82', 'KIM-0112_izah.png'),
  ('KIM-0113', 'Üzvi kimya', 'Alkanlar', 'aciq_eded', '15 q alkanın tam yanmasından 44 q karbon $\mathrm{(IV)}$ oksid ayrılmışsa, reaksiyadan neçə qram su alınar? $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '27', '3', 'Molekulunda n sayda karbon atomu olan alkanın bir molunun tam yanma tənliyi aşağıdakı kimidir. CnH2n+2 + 3 → 1 2 n $\mathrm{+\cdot O_{2}}$ $\mathrm{nCO_{2} + (n+1)H_{2}O}$ Reaksiya tənliyinə əsasən uyğun hesablamaları aparaq 14n+2 q alkan ---------------44n q $\mathrm{CO_{2}}$ 15 q alkan -----------------44 q $\mathrm{CO_{2}}$ n=2 deməli alkan $\mathrm{C_{2}H_{6}}$ dır. 15 q etanın tam yanmasından alınan suyun kütləsini (q) hesablayaq $\mathrm{C_{2}H_{6} \rightarrow 3H_{2}O}$ 30 q $\mathrm{C_{2}H_{6}-----------54}$ q $\mathrm{H_{2}O}$ 15 q $\mathrm{C_{2}H_{6}------------x}$ q $\mathrm{H_{2}O}$ x=27', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №83', 'KIM-0113_izah.png'),
  ('KIM-0114', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'aciq_eded', '→ $\mathrm{CuO}$, t → $\mathrm{+C^{2}H^{5}OH}$ 2 $\mathrm{C_{2}H_{5}-CH-CH_{3}}$ + 3 + $\mathrm{CH_{3}-CH-CH_{3}}$ 1 5 4 $\mathrm{+CH_{3}CH_{2}CH_{2}OH}$ $\mathrm{CH_{3}OH+}$ $\mathrm{OH}$ $\mathrm{OH}$ Hansı reaksiyalarda keton alınır?', 'KIM-0114.png', NULL::text, '1,3', '3', 'Məlumdur ki, ikili spirtlərin $\mathrm{CuO}$ ilə reaksiyasından ketonlar alınır. Verilmiş reaksiyalardan yalnız birinci və üçüncü reaksiyalarda götürülən spirtlər ikilidir. Deməli, birinci və üçüncü reaksiyalardan keton alınacaq.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №84', 'KIM-0114_izah.png'),
  ('KIM-0115', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'aciq_eded', '$\mathrm{C_{x}H_{y}O_{z}+}$ $\mathrm{4O_{2} \rightarrow 3CO_{2}+}$ $\mathrm{4H_{2}O}$ tənliyinə əsasən $\mathrm{C_{x}H_{y}O_{z}}$-in 1 molekulunda neçə atom var?', NULL::text, NULL::text, '13', '3', '$\mathrm{C_{x}H_{y}O_{z}+}$ $\mathrm{4O_{2} \rightarrow 3CO_{2}+}$ $\mathrm{4H_{2}O}$ reaksiya tənliyinin əmsallaşdırılmış formasından aydın olur ki, $\mathrm{C_{x}H_{y}O_{z}}$ maddəsinin molekulunda 3 karbon, 8 hidrogen və 2 oksigen atomu var.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №85', 'KIM-0115_izah.png'),
  ('KIM-0116', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'aciq_eded', '44,8 l (n.ş.) azotdan neçə qram 60%-li nitrat turşusu almaq olar? $\mathrm{M_{r}(HNO_{3})=63}$', NULL::text, NULL::text, '420', '3', 'Azotdan nitrat turşusunun alınması sadə sxemlə ifadə etsək $\mathrm{N_{2} \rightarrow 2HNO_{3}}$ 22,4 litr (n.ş) $\mathrm{N_{2}---------126}$ q $\mathrm{HNO_{3}}$ alınır 44,8 litr (n.ş) $\mathrm{N_{2}}$ -----------x q $\mathrm{HNO_{3}}$ x= 252 q 252-------------60% y ---------------100% y=420 q', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №86', 'KIM-0116_izah.png'),
  ('KIM-0123', 'Qeyri-üzvi kimya', 'Metallar', 'aciq_eded', 'Tərkibində kütləcə 25% sink olan $\mathrm{Zn}$ və $\mathrm{Cu}$ qarışığının xlorid turşusu ilə tam reaksiyasından 0,4 mol $\mathrm{H_{2}}$ ayrılmışsa, qarışıqda neçə qram mis olmuşdur? $\mathrm{A_{r}(Zn)=65}$ A) 72 B) 56 C) 86 D)) 78 E) 44', NULL::text, NULL::text, '78', '3', '$\mathrm{Cu + HCl}$ → reaksiya getmir x q ------------------------ 0,4 mol $\mathrm{Zn + 2HCl \rightarrow ZnCl_{2} + H_{2}}$ 65 q ----------------------- 1 mol x = 26 q $\mathrm{Zn}$ olur Qarışıqda sinkin kütləsi 25% olduğunu nəzərə alsaq 26 q $\mathrm{Zn}$ --------- 25% y q $\mathrm{Cu}$ ----------- 75% y = 78 q', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №63', 'KIM-0123_izah.png'),
  ('KIM-0125', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'aciq_eded', '1 mol $\mathrm{Na_{2}SO_{4}}$-ün tam dissosiasiyasından cəmi neçə mol ion əmələ gələr? A) 4 B) 7 C) 6 D)) 3 E) 2', NULL::text, NULL::text, '3', '3', '$\mathrm{Na_{2}SO_{4}\nu}$ $\mathrm{2Na^{+}+}$ $\mathrm{SO_{4}^{2-}}$ dissosiasiya tənliyindən görünür ki, 1 mol natrium-sulfat tam dissosiasiya etdikdə cəmi 3 mol ion əmələ gəlir.', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №65', 'KIM-0125_izah.png'),
  ('KIM-0128', 'Ümumi kimya', 'Kimyəvi rabitə və hibridləşmə', 'aciq_eded', 'Etilen molekulunda cəmi neçə σ-rabitə var? A) 4 B) 6 C) 7 D)) 5 E) 8', NULL::text, NULL::text, '5', '3', 'Alifatik karbohidrogenlərdə siqma rabitələrin sayını tapmaq üçün indekslərin cəmindən bir çıxmaq lazımdır. Etilen $\mathrm{(C_{2}H_{4})}$ molekulunda olan siqma rabitələrin sayı = 2 + 4 – 1 = 5 olur', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №68', 'KIM-0128_izah.png'),
  ('KIM-0129', 'Ümumi kimya', 'Məhlullar', 'aciq_eded', '20 q şəkəri neçə qram suda həll etmək lazımdır ki, 20%-li məhlul alınsın? A)) 80 B) 50 C) 20 D) 60 E) 40', NULL::text, NULL::text, '80', '3', '% 20 % 100 20 20 = ⋅ + su m , msu+20=100, msu=80', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №69', 'KIM-0129_izah.png'),
  ('KIM-0133', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'aciq_eded', '1 mol $\mathrm{H_{3}PO_{4}}$ + x mol $\mathrm{NaOH}$ → 1 mol normal duz + x mol $\mathrm{H_{2}O}$ 1 mol $\mathrm{H_{2}SO_{4}}$ + y mol $\mathrm{NaOH}$ → 1 mol turş duz + y mol $\mathrm{H_{2}O}$ 1 mol $\mathrm{HPO_{3}}$ + z mol $\mathrm{NaOH}$ → 1 mol normal duz + z mol $\mathrm{H_{2}O}$ Reaksiya sxemlərinə əsasən x + y + z cəmini hesablayın. A) 3 B)) 5 C) 6 D) 7 E) 4', 'KIM-0133.png', NULL::text, '5', '3', '1 mol $\mathrm{H_{3}PO_{4}+}$ 3 mol $\mathrm{NaOH}$ → 1 mol Na3PO4(normal duz) + 3 mol $\mathrm{H_{2}O}$ reaksiyasından normal duz alınıbsa, x = 3 olur. 1 mol $\mathrm{H_{2}SO_{4}+}$ 1 mol $\mathrm{NaOH}$ → 1 mol NaHSO4(turş duz) + 1 mol $\mathrm{H_{2}O}$ reaksiyasından turş duz alınıbsa, y = 1 olur. 1 mol $\mathrm{HPO_{3}+}$ 1 mol $\mathrm{NaOH}$ → 1 mol NaPO3(normal duz) + 1 mol $\mathrm{H_{2}O}$ reaksiyasına əsasən z = 1 olur. x + y + z = 5', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №73', 'KIM-0133_izah.png'),
  ('KIM-0139', 'Üzvi kimya', 'Karbon turşuları', 'aciq_eded', '$\mathrm{M_{r}(CH_{3}COOH)}$ Mr(butan turşusu) 60 x Homoloji fərqdən $\mathrm{(CH_{2})}$ istifadə edərək, x-i hesablayın. $\mathrm{A_{r}(C)=12}$; $\mathrm{A_{r}(H)=1}$ A) 116 B) 130 C) 74 D)) 88 E) 46', 'KIM-0139.png', NULL::text, '88', '3', 'Butan turşusunun formulu $\mathrm{C_{3}H_{7}COOH}$ –dır. Kimyəvi formullardan görünür ki, butan turşusu etan turşusundan 2 $\mathrm{CH_{2}}$ qrupu qədər fərqlənir. Deməli $\mathrm{M_{r}(C_{3}H_{7}COOH)}$ = 88 olacaq.', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №79', 'KIM-0139_izah.png'),
  ('KIM-0140', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'aciq_eded', 'ayrılan istilik, kC $\mathrm{m(C_{2}H_{2}),}$ q a → b 1300 13 $\mathrm{2C_{2}H_{2} + 5O_{2} \rightarrow 4CO_{2} + 2H_{2}O}$ + 2600 kC Reaksiya tənliyinə əsasən a b nisbətini hesablayın. $\mathrm{M_{r}(C_{2}H_{2})=26}$ A) 50 B) 30 C) 20 D)) 25 E) 10', 'KIM-0140.png', NULL::text, '25', '3', 'b q --------------------------------------1300 kC $\mathrm{2C_{2}H_{2} + 5O_{2} \rightarrow 4CO_{2} + 2H_{2}O}$ + 2600 kC 52 q ------------------------------------ 2600 kC b = 26 q 13 q -------------------------------------- a kC $\mathrm{2C_{2}H_{2} + 5O_{2} \rightarrow 4CO_{2} + 2H_{2}O}$ + 2600 kC 52 q ------------------------------------ 2600 kC a = 650 kC a b = 25', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №80', 'KIM-0140_izah.png'),
  ('KIM-0141', 'Üzvi kimya', 'Alkinlər', 'aciq_eded', 'Maddə Molekulunda atomların ümumi sayı a b nisbəti Benzol a x Asetilen b x-i hesablayın. A)) 3 B) 4 C) 5 D) 6 E) 7', 'KIM-0141.png', NULL::text, '3', '3', 'Benzol $\mathrm{(C_{6}H_{6})}$ molekulunda 12, asetilen $\mathrm{(C_{2}H_{2})}$ molekulunda isə 4 atom var . a b = 3', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №81', 'KIM-0141_izah.png'),
  ('KIM-0143', 'Ümumi kimya', 'Oksidləşmə-reduksiya reaksiyaları', 'aciq_eded', '$\mathrm{Cu + HNO_{3} \rightarrow Cu(NO_{3})_{2}+}$ $\mathrm{NO + H_{2}O}$ Oksidləşdiricinin əmsalı Suyun əmsalı x y Reaksiya tənliyini əmsallaşdırın və x y nisbətini hesablayın. A)) 2 B) 3 C) 9 D) 4 E) 6', 'KIM-0143.png', NULL::text, '2', '3', 'Verilmiş reaksiya tənliyində $\mathrm{Cu}$ – reduksiyaedici, $\mathrm{HNO_{3}}$ isə oksidləşdiricidir. Bu tənliyi əmsallaşdırsaq 3Cu + $\mathrm{8HNO_{3} \rightarrow 3Cu(NO_{3})_{2}+}$ $\mathrm{2NO + 4H_{2}O}$ x = 8, y = 4 olduğunu müəyyən edərik. Deməli x y = 2 olur', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №83', 'KIM-0143_izah.png'),
  ('KIM-0144', 'Üzvi kimya', 'Tsikloalkanlar', 'aciq_eded', 'Karbohidrogen Molekulunda neytron sayı Nisbi molekul kütləsi Tsikloalkan 18 x x-i hesablayın. ( ) 12 1 6 1 C; H A)) 42 B) 56 C) 70 D) 84 E) 98', 'KIM-0144.png', NULL::text, '42', '3', 'Tsikloalkanlar $\mathrm{C_{n}H_{2n}}$ ümumi formuluna malikdir. Ümumi formula əsasən neytron sayı (12-6)n=6n olacaq. 6n = 18, n = 3. n-in qiymətini ümumi formulda nəzərə alsaq $\mathrm{M_{r}(C_{n}H_{2n})}$ = 14n = 14 · 3 = 42 olur', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №84', 'KIM-0144_izah.png'),
  ('KIM-0145', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'aciq_eded', '2 mol $\mathrm{KNO_{3}}$-ün tam termiki parçalanmasından neçə mol $\mathrm{O_{2}}$ əmələ gələr? A)) 1 B) 2 C) 0,5 D) 3 E) 1,5 A)) 1 B) 2 C) 0,5 D) 3 E) 1,5', NULL::text, NULL::text, '1', '3', '$\mathrm{KNO_{3}}$-ün parçalanma reaksiyasını yazıb, əmsallaşadıraq. $\mathrm{2KNO_{3}}$ t → $\mathrm{2KNO_{2} + O_{2}}$ reaksiya tənliyinə əsasən 2 mol $\mathrm{KNO_{3}}$-dən 1 mol $\mathrm{O_{2}}$ alınır.', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №85', 'KIM-0145_izah.png'),
  ('KIM-0146', 'Üzvi kimya', 'Karbon turşuları', 'aciq_eded', 'CnH2n–1COOH ümumi formuluna uyğun olan turşuları müəyyən edin. 1. Etan turşusu 2. Stearin turşusu 3. Olein turşusu 4. Akril turşusu A)) 3, 4 B) 1, 2 C) 2, 3 D) 2, 4 E) 1, 3', NULL::text, NULL::text, '34', '3', 'Etan və stearin turşuları doymuş birəsaslı karbon turşuları olduğundan $\mathrm{C_{n}H_{2n+1}COOH}$ ümumi formuluna malikdirlər. Olein və akril turşularının molekulunda karbon atomları arasında bir ikiqat rabitə olduğundan onlar CnH2n–1COOH ümumi formuluna malikdirlər.', '{1}', '2026', '2026-07-12 qəbul, I qrup, A variantı №86', 'KIM-0146_izah.png'),
  ('KIM-0151', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', '$\mathrm{HCOOH(m)+CH_{3}OH(m) \rightleftharpoons HCOOCH_{3}(m)+H_{2}O(m)}$ reaksiyasında tarazlığı $\mathrm{HCOOCH_{3}}$ alınması istiqamətinə necə yönəltmək olar? 1. Qarışqa turşusunu çıxarmaqla 2. Metanol əlavə etməklə 3. $\mathrm{HCOOCH_{3}}$ çıxarmaqla 4. Su əlavə etməklə', NULL::text, '{"A": "1, 3", "B": "2, 3", "C": "1, 4", "D": "2, 4", "E": "1, 2"}', 'B', '3', 'Bu test tapşırığında Le-Şatelye prinsipinə əsasən reaksiyanın istiqamətini $\mathrm{HCOOCH_{3}}$ tərəfə yönəltmək üçün metanol əlavə etmək və $\mathrm{HCOOCH_{3}}$ sistemdən çıxarmaq lazımdır.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №61', 'KIM-0151_izah.png'),
  ('KIM-0152', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Tərkibində peptid rabitəsi olan polimeri müəyyən edin.', NULL::text, '{"A": "lavsan", "B": "polistirol", "C": "zülal", "D": "polimetilmetakrilat", "E": "nişasta"}', 'C', '3', 'Lavsan, polistirol və polimetilmetakrilatın tərkibində mürəkkəb efir qrupu, nişastanın tərkibində sadə efir qrupu, zülalın tərkibində isə peptid rabitəsi (qrupu) var.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №62', 'KIM-0152_izah.png'),
  ('KIM-0153', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'Kaliumun su ilə reaksiyasından hansı maddələr alınır?', NULL::text, '{"A": "$\\mathrm{K_{2}O}$ və $\\mathrm{H_{2}}$", "B": "$\\mathrm{K_{2}O_{2}}$ və $\\mathrm{H_{2}}$", "C": "$\\mathrm{KOH}$ və $\\mathrm{O_{2}}$", "D": "$\\mathrm{KH}$ və $\\mathrm{O_{2}}$", "E": "$\\mathrm{KOH}$ və $\\mathrm{H_{2}}$"}', 'E', '3', 'Qələvi və qələvi torpaq metallar su ilə reaksiyaya daxil olduqda qələvi və hidrogen qazı əmələ gəlir. 2K + $\mathrm{2H_{2}O \rightarrow 2KOH + H_{2}}$', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №63', 'KIM-0153_izah.png'),
  ('KIM-0154', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'qapali', 'Hansı maddənin tərkibində karbon atomu var?', NULL::text, '{"A": "pirit", "B": "silan", "C": "çay sodası", "D": "təbii gips", "E": "kvars qumu"}', 'C', '3', 'Verilmiş maddələrdən formulları: pirit - $\mathrm{FeS_{2}}$ , silan – $\mathrm{SiH_{4}}$ , çay sodası – $\mathrm{NaHCO_{3},}$ təbii gips – $\mathrm{CaSO_{4}\cdot2H_{2}O}$ , kvars qumu – $\mathrm{SiO_{2}.}$ Verilənlərdən yalnız çay sodasının tərkibində karbon atomu var.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №64', 'KIM-0154_izah.png'),
  ('KIM-0155', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', 'Hansı reaksiya qatı sulfat turşusunun xassəsini əks etdirmir?', 'KIM-0155.png', '{"A": "$\\mathrm{Cr + H_{2}SO_{4}}$ t → $\\mathrm{Cr_{2}(SO_{4})_{3}}$ + …", "B": "$\\mathrm{Fe + H_{2}SO_{4} \\rightarrow H_{2}}$ + …", "C": "$\\mathrm{Zn + H_{2}SO_{4}}$ t → $\\mathrm{H_{2}O}$ + …", "D": "$\\mathrm{Na + H_{2}SO_{4} \\rightarrow H_{2}S}$ + …", "E": "$\\mathrm{Cu + H_{2}SO_{4}}$ t → $\\mathrm{CuSO_{4}}$ + …"}', 'B', '3', 'Qatı sulfat turşusunun metallarla reaksiyasından hidrogenin ayrılması onun xassəsini əks etdirmir. Bu duru sulfat turşusunun xassəsini göstərir.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №65', 'KIM-0155_izah.png'),
  ('KIM-0156', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'qapali', 'Oksigen hansı metallarla qarşılıqlı təsirdə olmur?', NULL::text, '{"A": "$\\mathrm{Mg}$, $\\mathrm{Fe}$", "B": "$\\mathrm{Mg}$, K", "C": "$\\mathrm{Ag}$, $\\mathrm{Au}$", "D": "$\\mathrm{Na}$, $\\mathrm{Ca}$", "E": "K, $\\mathrm{Ca}$"}', 'C', '3', 'Oksigen qazı $\mathrm{Ag}$, $\mathrm{Au}$ və Pt ilə reaksiyaya daxil olmur.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №66', 'KIM-0156_izah.png'),
  ('KIM-0157', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', '$\mathrm{HXO_{3}}$ və $\mathrm{XH_{3}}$ birləşmələrində X hansı element ola bilər?', NULL::text, '{"A": "$\\mathrm{Cl}$", "B": "$\\mathrm{Si}$", "C": "C", "D": "S", "E": "N"}', 'E', '3', 'Verilmiş elementlərdən yalnız azot $\mathrm{HXO_{3}}$ yəni $\mathrm{HNO_{3}}$ və $\mathrm{XH_{3}}$ yəni $\mathrm{NH_{3}}$ tipli birləşmələr əmələ gətirə bilir.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №67', 'KIM-0157_izah.png'),
  ('KIM-0158', 'Ümumi kimya', 'Məhlullar', 'qapali', '460 q suda 40 q natrium-hidroksid həll edildi. Alınmış məhlulda natrium-hidroksidin kütlə payını (%) hesablayın.', NULL::text, '{"A": "8", "B": "16", "C": "10", "D": "24", "E": "20"}', 'A', '3', '40 q natrium-hidroksidi 460 q suda həll etdikdə məhlulun kütləsi 500 q olur (40 q + 460 q). Alınmış məhlulda natrium-hidroksidin kütlə payı: ω= 40 40 460 + ⋅ 100% = 8%', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №68', 'KIM-0158_izah.png'),
  ('KIM-0159', 'Ümumi kimya', 'Kimyəvi rabitə və hibridləşmə', 'qapali', 'Hansı maddə molekulunda kimyəvi rabitələrin yaranmasında 6 elektron iştirak edir?', NULL::text, '{"A": "$\\mathrm{Cl_{2}}$", "B": "$\\mathrm{O_{2}}$", "C": "$\\mathrm{H_{2}}$", "D": "$\\mathrm{F_{2}}$", "E": "$\\mathrm{N_{2}}$"}', 'E', '3', 'Bir rabitənin yaranmasında 2 elektron iştirak edir. Verilmiş molekulların quruluş formullarına nəzər yetirsək: $\mathrm{Cl-Cl}$, $\mathrm{O=O}$, $\mathrm{H-H}$ , $\mathrm{F-F}$, $\mathrm{N\equivN}$ yalnız azot molekulunda rabitələrin yaranmasında 6 elektron iştirak edir.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №69', 'KIM-0159_izah.png'),
  ('KIM-0160', 'Üzvi kimya', 'Alkanlar', 'qapali', 'Verilmiş birləşmənin molekulunda neçə ədəd dördlü karbon atomu var? $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$ C $\mathrm{CH_{2}}$ $\mathrm{CH_{2}}$ $\mathrm{CH}$ $\mathrm{CH}$ $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$ C $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$ $\mathrm{CH_{3}}$', 'KIM-0160.png', '{"A": "5", "B": "2", "C": "4", "D": "1", "E": "3"}', 'B', '3', 'Məlumdur ki, dörd karbon atomu ilə birləşmiş karbon atomları dördlü hesab olunur. Verilmiş birləşmənin quruluş formulunda göründüyü kimi 2 ədəd dördlü karbon atomu var.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №70', 'KIM-0160_izah.png'),
  ('KIM-0161', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Hansı kimyəvi birləşmədə elementlərin kütlə nisbəti düzgün göstərilib? $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(O)=16,}$ $\mathrm{A_{r}(S)=32}$ Kimyəvi birləşmə Kütlə nisbəti', 'KIM-0161.png', '{"A": "$\\mathrm{H_{2}S}$ 1:4", "B": "$\\mathrm{H_{2}O}$ 1:2", "C": "$\\mathrm{CO}$ 3:4", "D": "$\\mathrm{CO_{2}}$ 4:3", "E": "$\\mathrm{SO_{2}}$ 2:1"}', 'C', '3', 'Təqdim olunmuş test tapşırığını yerinə yetirmək üçün birləşmədə olan hər bir elementin nisbi atom kütləsini atom sayına vurub və onların nisbəti müəyyən edilir. Yalnız $\mathrm{CO}$ birləşməsi üçün bu nisbət doğru göstərilib: $\mathrm{A_{r}(C)}$ : $\mathrm{A_{r}(O)}$ = 12 : 16, bu ədədləri 4-ə ixtisar etdikdə nisbət 3: 4 kimi olur.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №71', 'KIM-0161_izah.png'),
  ('KIM-0162', 'Üzvi kimya', 'Karbon turşuları', 'qapali', 'Maddə Kütləsi, q Oksigen atomlarının sayı CnH2nO2 18,5 0,5 $\mathrm{N_{A}}$ n-i hesablayın. $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', 'KIM-0162.png', '{"A": "4", "B": "2", "C": "5", "D": "3", "E": "1"}', 'D', '3', 'İlk öncə maddənin nisbi molekul kütləsi hesablanılır: $\mathrm{Mr(C_{n}H_{2n}O_{2})=12n+2n+32=14n+32.}$ Daha sonra tənasüb quruluraq n-nin qiyməti müəyyən olunur: 14n+32 ------------------ 2 $\mathrm{N_{A}}$ 18,5 ------------------ 0,5 $\mathrm{N_{A}}$ n=3', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №72', 'KIM-0162_izah.png'),
  ('KIM-0163', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'Hansı reaksiyadan mis alınır?', NULL::text, '{"A": "$\\mathrm{CuO + H_{2}}$ t →", "B": "$\\mathrm{Cu(OH)_{2}}$ t →", "C": "$\\mathrm{CuCO_{3}}$ t →", "D": "$\\mathrm{CuO + H_{2}SO_{4}}$ →", "E": "$\\mathrm{Cu(NO_{3})_{2}}$ t →"}', 'A', '3', 'Verilmiş reaksiyaları məhsullarını yazaraq misin hansı reaksiya üzrə alındığını müəyyən edirik. $\mathrm{CuO + H_{2}}$ t → $\mathrm{Cu + H_{2}O}$ $\mathrm{Cu(OH)_{2}}$ t → $\mathrm{CuO + H_{2}O}$ $\mathrm{CuCO_{3}}$ t → $\mathrm{CuO + CO_{2}}$ $\mathrm{CuO + H_{2}SO_{4} \rightarrow CuSO_{4} + H_{2}O}$ $\mathrm{Cu(NO_{3})_{2}}$ t → $\mathrm{CuO + NO_{2} + H_{2}O}$', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №73', 'KIM-0163_izah.png'),
  ('KIM-0164', 'Ümumi kimya', 'Elektroliz', 'qapali', '$\mathrm{NaOH}$-ın suda məhlulunun elektrolizi zamanı anodda 50 ml (n.ş.) qaz ayrılıb. Katodda neçə ml qaz ayrılar?', NULL::text, '{"A": "60", "B": "50", "C": "25", "D": "100", "E": "40"}', 'D', '3', 'Məlum olduğu kimi $\mathrm{NaOH}$-ın suda məhlulunun elektrolizi zamanı yalnız su elektrolizə uğrayır, katodda hidrogen anodda isə oksigen ayrılır. x ml 50 ml $\mathrm{2H_{2}O}$ el-z → $\mathrm{2H_{2} + O_{2}}$ 44,8 l 22,4 l x= 50 44,8 100 22,4 ml ⋅ =', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №74', 'KIM-0164_izah.png'),
  ('KIM-0165', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', '$\mathrm{C_{x}H_{6}}$ molekulunda bir ədəd ikiqat rabitə var. Bu birləşmə hansı polimeri əmələ gətirir?', 'KIM-0165.png', '{"A": "$\\mathrm{CH_{2}}$ $\\mathrm{CH_{2}}$ $\\mathrm{_{n}}$", "B": "$\\mathrm{CH_{2}}$ $\\mathrm{CH}$ $\\mathrm{CH_{3}}$ $\\mathrm{_{n}}$", "C": "$\\mathrm{CH}$ C $\\mathrm{CH_{3}}$ $\\mathrm{_{n}}$", "D": "$\\mathrm{CH_{2}}$ $\\mathrm{CH}$ $\\mathrm{C_{6}H_{5}}$ $\\mathrm{_{n}}$", "E": "$\\mathrm{CH_{2}}$ C $\\mathrm{CH}$ $\\mathrm{CH_{2}}$ $\\mathrm{CH_{3}}$ $\\mathrm{_{n}}$"}', 'B', '3', '$\mathrm{C_{3}H_{6}}$ molekulunda bir ədəd ikiqat rabitə var. Onun polimerləşməsindən alınan polimerin formulu isə aşağıdakı kimidir: $\mathrm{CH_{2}}$ $\mathrm{CH}$ $\mathrm{CH_{3}}$ $\mathrm{_{n}}$', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №75', 'KIM-0165_izah.png'),
  ('KIM-0166', 'Qeyri-üzvi kimya', 'Fosfor və mineral gübrələr', 'qapali', 'Cədvələ əsasən fosforun X, Y və Z turşularını adlandırın. Fosforun turşuları Molekulunda atomların ümumi sayı X 5 Y 8 Z 13 X Y Z', 'KIM-0166.png', '{"A": "pirofosfat metafosfat ortofosfat", "B": "ortofosfat metafosfat pirofosfat", "C": "metafosfat pirofosfat ortofosfat", "D": "metafosfat ortofosfat pirofosfat", "E": "ortofosfat pirofosfat metafosfat"}', 'D', '3', 'Metafosfat turşusu $\mathrm{(HPO_{3})}$ molekulunda atomların sayı 5, ortofosfat turşusunda $\mathrm{(H_{3}PO_{4})}$ bu say 8, pirofosfat turşusunda $\mathrm{(H_{4}P_{2}O_{7})}$ isə 13 olur.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №76', 'KIM-0166_izah.png'),
  ('KIM-0167', 'Üzvi kimya', 'Alkanlar', 'qapali', '3 q alkan tam yandıqda 8,8 q karbon qazı alınır. Bu alkanın formulunu müəyyən edin. $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, '{"A": "$\\mathrm{C_{3}H_{8}}$", "B": "$\\mathrm{C_{2}H_{6}}$", "C": "$\\mathrm{CH_{4}}$", "D": "$\\mathrm{C_{4}H_{10}}$", "E": "$\\mathrm{C_{5}H_{12}}$"}', 'B', '3', '3 q ------------------ 8,8 q $\mathrm{C_{n}H_{2n+2} + (3n+1)/2O_{2}}$ $\mathrm{nCO_{2}+}$ (n+1) $\mathrm{H_{2}O}$ 14n+2 ----------------- 44n 3 ⋅44n=8,8(14n+2) 15n=14n+2 n=2', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №77', 'KIM-0167_izah.png'),
  ('KIM-0168', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', 'Etilen və etanı hansı maddənin suda məhlulu ilə fərqləndirmək olar?', NULL::text, '{"A": "dəmir $\\mathrm{(III)}$ xloridin", "B": "mis $\\mathrm{(II)}$ hidroksidin", "C": "natrium-hidroksidin", "D": "kalium-permanqanatın", "E": "natrium-xloridin"}', 'D', '3', 'Etilen etandan fərqli olaraq kalium-permanqanatın suda məhlulunu rəngsizləşdirir. Çünki molekulunda karbon atomları arasında π(pi)- rabitəsi var.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №78', 'KIM-0168_izah.png'),
  ('KIM-0169', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', 'Maddə Yanma istiliyi, kC/mol $\mathrm{C_{3}H_{6}}$ 1440 0,4 mol $\mathrm{C_{3}H_{6}}$-nın tam yanmasından ayrılan istiliyin miqdarını (kC) hesablayın.', 'KIM-0169.png', '{"A": "486", "B": "540", "C": "392", "D": "628", "E": "576"}', 'E', '3', 'Yanma istiliyi maddənin 1 molunun tam yanması zamanı ayrılan istiliyin miqdarına bərabərdir. 1 mol --------- 1440 kC 0,4 mol --------- x kC x=576 kC', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №79', 'KIM-0169_izah.png'),
  ('KIM-0171', 'Üzvi kimya', 'Alkinlər', 'qapali', 'Hansı maddə $\mathrm{C_{n}H_{2n-2}}$ formuluna uyğundur?', NULL::text, '{"A": "$\\mathrm{CH_{3}}$ $\\mathrm{CH}$ $\\mathrm{CH}$ $\\mathrm{CH_{3}}$", "B": "$\\mathrm{CH_{3}}$ C C $\\mathrm{CH_{3}}$", "C": "$\\mathrm{CH_{3}}$ $\\mathrm{CH_{2}}$ $\\mathrm{CH_{3}}$", "D": "$\\mathrm{CH_{3}}$ $\\mathrm{CH}$ $\\mathrm{CH_{2}}$", "E": "$\\mathrm{CH_{2}}$ $\\mathrm{CH_{2}}$"}', 'B', '3', '$\mathrm{C_{n}H_{2n-2}}$ alkin və alkadiyenlərin ümumi formuludur. Bu birləşmələrdə 2 ədəd pi-rabitəsi var. Buna əsasən cavab $\mathrm{CH^{3}}$ C C $\mathrm{CH^{3}}$ olacaq.', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №81', 'KIM-0171_izah.png'),
  ('KIM-0172', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Hansı sxemdə X maddəsi nitrat turşusudur?', 'KIM-0172.png', '{"A": "X + $\\mathrm{CaO \\rightarrow Ca(NO_{3})_{2}+}$ $\\mathrm{H_{2}O}$", "B": "X + $\\mathrm{CO_{2} \\rightarrow CO(NH_{2})_{2}+}$ $\\mathrm{H_{2}O}$", "C": "X + $\\mathrm{NH_{3} \\rightarrow NO + H_{2}O}$", "D": "X + $\\mathrm{Na_{2}CO_{3} \\rightarrow NaNO_{3}+}$ $\\mathrm{NaNO_{2} + CO_{2}}$", "E": "X + $\\mathrm{KOH \\rightarrow KNO_{3}+}$ $\\mathrm{NH_{3} + H_{2}O}$"}', 'A', '3', '$\mathrm{HNO_{3} + CaO \rightarrow Ca(NO_{3})_{2}+}$ $\mathrm{H_{2}O}$ $\mathrm{NH_{3}+}$ $\mathrm{CO_{2} \rightarrow CO(NH_{2})_{2}+}$ $\mathrm{H_{2}O}$ $\mathrm{O_{2} + NH_{3} \rightarrow NO + H_{2}O}$ $\mathrm{NO_{2} + Na_{2}CO_{3} \rightarrow NaNO_{3}+}$ $\mathrm{NaNO_{2} + CO_{2}}$ $\mathrm{NH_{4}NO_{3} + KOH \rightarrow KNO_{3}+}$ $\mathrm{NH_{3} + H_{2}O}$', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №82', 'KIM-0172_izah.png'),
  ('KIM-0173', 'Ümumi kimya', 'Oksidləşmə-reduksiya reaksiyaları', 'aciq_eded', 'Reaksiya tənliyində reduksiyaedicinin əmsalının oksidləşdiricinin əmsalına olan nisbətini hesablayın. P + $\mathrm{KClO_{3}}$ $\mathrm{KCl + P_{2}O_{5}}$', NULL::text, NULL::text, '1,2', '3', '6P + $\mathrm{5KClO_{3}}$ $\mathrm{6KCl + 3P_{2}O_{5}}$ Oksidləşdirici: $\mathrm{KClO_{3}}$ (əmsalı 5) Reduksiyaedici: P (əmsalı 6) Nisbəti: 6 1,2 5 =', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №83', 'KIM-0173_izah.png'),
  ('KIM-0174', 'Ümumi kimya', 'Atomun quruluşu və dövri sistem', 'aciq_eded', 'Elementlər Nisbi atom kütləsi Proton sayı Neytron sayı X 16 8 a Y 31 b 16 a+b cəmini hesablayın.', 'KIM-0174.png', NULL::text, '23', '3', 'Nisbi atom kütləsi protonla neytronların sayları cəminə bərabərdir. a=16-8=8 , b=31-16=15 a+b=23', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №84', 'KIM-0174_izah.png'),
  ('KIM-0175', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'aciq_eded', 'Maddə Molekulunda atom sayı hidrogen karbon $\mathrm{C_{n}H_{2n+1}CHO}$ 4 x x-i müəyyən edin.', 'KIM-0175.png', NULL::text, '2', '3', 'Bu maddə molekulu üçün hidrogen atomlarının sayı 2n+2 formulu ilə hesablanacaq. 2n+2=4 n=1 $\mathrm{CH_{3}CHO}$ molekulunda 2 karbon atomu var', '{1}', '2026', '2026-06-07 qəbul, I qrup, A variantı №85', 'KIM-0175_izah.png'),
  ('KIM-0181', 'Üzvi kimya', 'Spirtlər', 'qapali', '120 q doymuş biratomlu spirtin $\mathrm{Na}$ ilə reaksiyasından $\mathrm{6,02\cdot 10^{23}}$ sayda hidrogen molekulu ayrılmışsa, spirtin formulunu müəyyən edin. $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, '{"A": "$\\mathrm{C_{3}H_{7}OH}$", "B": "$\\mathrm{CH_{3}OH}$", "C": "$\\mathrm{C_{4}H_{9}OH}$", "D": "$\\mathrm{C_{2}H_{5}OH}$", "E": "$\\mathrm{C_{5}H_{11}OH}$"}', 'A', '3', 'ᵥ(H2) = N : $\mathrm{N_{A}}$ = 6,02 ⋅ $\mathrm{10^{23}}$ : 6,02 ⋅ $\mathrm{10^{23}}$ = 1 mol 120 q 1 mol $\mathrm{2C_{n}H_{2n+1}OH}$ + 2Na → $\mathrm{2C_{n}H_{2n+1}ONa + H_{2}}$ 2(14n + 18) q 1 mol 28n + 36 =120 28n = 84 n = 3 $\mathrm{[C_{3}H_{7}OH]}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №61', 'KIM-0181_izah.png'),
  ('KIM-0182', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', 'Kükürd-dioksid üçün hansı ifadə doğrudur?', NULL::text, '{"A": "duz əmələgətirməyən oksiddir", "B": "oksigenlə reaksiyaya daxil olur", "C": "əsasi oksidlərlə qarşılıqlı təsirdə olmur", "D": "suda həll olduqda sulfat turşusu əmələ gəlir", "E": "qələvilərlə reaksiyaya daxil olmur"}', 'B', '3', 'Kükürd-dioksid $\mathrm{(SO_{2})}$ turşu oksididir. Əsasi oksid və qələvilərlə reaksiyaya daxil olur, suda həll olduqda sulfit turşusuna çevrilir. Oksigenlə katalitik oksidləşmə reaksiyasına daxil olub $\mathrm{SO_{3}}$ - ə çevrilir: $\mathrm{2SO_{2} + O_{2} \rightarrow 2SO_{3}}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №62', 'KIM-0182_izah.png'),
  ('KIM-0183', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'Maddələr Mol miqdarı Reaksiyaya tam daxil olduğu hidrogenin mol miqdarı $\mathrm{CuO}$ x n $\mathrm{WO_{3}}$ y 3n : y x nisbətini hesablayın.', 'KIM-0183.png', '{"A": "1", "B": "3", "C": "5", "D": "1,5", "E": "2"}', 'A', '3', 'x mol n mol $\mathrm{CuO + H_{2} \rightarrow Cu + H_{2}O}$ x = n mol 1 mol 1 mol y mol 3n mol $\mathrm{WO_{3}+}$ $\mathrm{3H_{2}}$ → W + $\mathrm{3H_{2}O}$ y = n mol 1 mol 3 mol y : x = n : n = 1', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №63', 'KIM-0183_izah.png'),
  ('KIM-0184', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', 'Hansı maddələrin qarşılıqlı təsirindən etilxlorid alınır?', NULL::text, '{"A": "$\\mathrm{CH_{4}}$ və $\\mathrm{Cl_{2}}$", "B": "$\\mathrm{C_{2}H_{2}}$ və $\\mathrm{Cl_{2}}$", "C": "$\\mathrm{C_{2}H_{6}}$ və $\\mathrm{HCl}$", "D": "$\\mathrm{C_{2}H_{4}}$ və $\\mathrm{HCl}$", "E": "$\\mathrm{C_{2}H_{2}}$ və $\\mathrm{HCl}$"}', 'D', '3', '$\mathrm{C_{2}H_{4} + HCl \rightarrow C_{2}H_{5}Cl}$ [etilxlorid]', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №64', 'KIM-0184_izah.png'),
  ('KIM-0186', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'qapali', 'Qarışqa turşusu və qarışqa aldehidi üçün ümumi olmayan nədir? I. Karbon atomunun oksidləşmə dərəcəsi II. Molekullarında $\mathrm{sp^{2}-}$ hibrid vəziyyətində olan karbon atomlarının sayı III. Adi şəraitdə aqreqat halları IV. $\mathrm{Cu(OH)_{2}}$ ilə reaksiyaya daxil olması', NULL::text, '{"A": "I, II", "B": "III, IV", "C": "I, III", "D": "I, IV", "E": "II, IV"}', 'C', '3', 'qarışqa turşusu: $\mathrm{HCOOH}$ qarışqa aldehidi: $\mathrm{HCHO}$ +2 0 I. ümumi olmayan; $\mathrm{HCOOH}$ $\mathrm{HCHO}$ $\mathrm{sp^{2}sp^{2}}$ II. ümumi olan; $\mathrm{HCOOH}$ $\mathrm{HCHO}$ III. ümumi olmayan; $\mathrm{HCOOH}$ – maye $\mathrm{HCHO}$ - qaz IV. ümumi olan; $\mathrm{HCOOH + 2Cu(OH)_{2}}$ t → $\mathrm{CO_{2} + 3H_{2}O + Cu_{2}O}$ $\mathrm{HCHO + 2Cu(OH)_{2}}$ t → $\mathrm{HCOOH + 2H_{2}O + Cu_{2}O}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №66', 'KIM-0186_izah.png'),
  ('KIM-0187', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Kalsium-oksidin neçə qramında 3,2 q kalsium olar? $\mathrm{M_{r}(CaO)=56,}$ $\mathrm{A_{r}(Ca)=40.}$', NULL::text, '{"A": "4,48", "B": "56", "C": "5,6", "D": "40", "E": "2,5"}', 'A', '3', 'x q 3,2 q $\mathrm{CaO \rightarrow Ca}$ x = 4,48 q 56 q 40 q', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №67', 'KIM-0187_izah.png'),
  ('KIM-0189', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Hansı maddələrin dehidrogenləşməsindən butadien- stirol kauçukunun monomerləri alınır?', NULL::text, '{"A": "buten-2, o-ksilol", "B": "butan, etilbenzol", "C": "heksan, propilbenzol", "D": "butan, tsikloheksan", "E": "buten-1, p-ksilol"}', 'B', '3', '$\mathrm{C_{4}H_{10} \rightarrow CH_{2} = CH - CH = CH_{2} + 2H_{2}}$ [butan] [butadien-1,3] $\mathrm{C_{6}H_{5} - CH_{2} - CH_{3} \rightarrow C_{6}H_{5} - CH = CH_{2} + H_{2}}$ [etilbenzol] [stirol] Butadien-1,3 və stirolun birgə polimerləşməsindən butadien-stirol kauçuku alınır.', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №69', 'KIM-0189_izah.png'),
  ('KIM-0190', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Hansı liflərin alınmasında aminturşulardan istifadə olunur? I. kapron II. neylon III. lavsan IV. enant', 'KIM-0190.png', '{"A": "I, IV", "B": "II, III", "C": "yalnız I", "D": "I, II", "E": "yalnız III"}', 'A', '3', 'I. doğru; kapron lifinin alınmasında ε-aminkapron turşusundan istifadə olunur II. səhv; neylon lifinin alınmasında heksametilendiamin və adipin turşusundan istifadə olunur III. səhv; lavsan lifinin alınmasında tereftal turşusu və etilenqlikoldan istifadə olunur IV. doğru; enant lifinin alınmasında ω-aminenant turşusundan istifadə olunur', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №70', 'KIM-0190_izah.png'),
  ('KIM-0191', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', 'Eyni mol miqdarda azot və X qazını qarışdırdıqda havadan ağır qaz qarışığı alınır. X qazını müəyyən edin. $\mathrm{A_{r}(N)=14,}$ $\mathrm{A_{r}(O)=16,}$ $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ Morta(hava)=29 q/mol.', NULL::text, '{"A": "$\\mathrm{C_{2}H_{2}}$", "B": "$\\mathrm{NH_{3}}$", "C": "$\\mathrm{CH_{4}}$", "D": "$\\mathrm{O_{2}}$", "E": "$\\mathrm{H_{2}}$"}', 'D', '3', 'Eyni mol miqdarında götürülmüş azot qazı $\mathrm{(N_{2})}$ ilə nisbi molekul kütləsi havanın orta molyar kütləsindən böyük olan $\mathrm{O_{2}}$ qazını qarışdırdıqda alınan qarışığın orta molyar kütləsi 29 q/mol-dan böyük olur.', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №71', 'KIM-0191_izah.png'),
  ('KIM-0192', 'Ümumi kimya', 'Kimyəvi rabitə və hibridləşmə', 'qapali', 'Maddələr Molekulunda kimyəvi rabitələrin yaranmasında iştirak edən hibrid orbitalların sayı ammonyak x su y x+y cəmini hesablayın.', 'KIM-0192.png', '{"A": "7", "B": "9", "C": "5", "D": "6", "E": "4"}', 'C', '3', 'Ammonyak $\mathrm{(NH_{3})}$ molekulunda azot atomu $\mathrm{sp^{3}-}$ hibridləşmə halındadır və azotun 4 hibrid orbitalından üçü hidrogenin s-orbitalı ilə örtülərək rabitə əmələ gətirir: x = 3 Su $\mathrm{(H_{2}O)}$ molekulunda oksigen atomu sp3-hibridləşmə halındadır və oksigenin 4 hibrid orbitalından ikisi hidrogenin s-orbitalı ilə örtülərək rabitə əmələ gətirir: y = 2', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №72', 'KIM-0192_izah.png'),
  ('KIM-0193', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'qapali', 'Hansı reaksiya nəticəsində alınan maddələrdən biri natrium-hidroksid məhlulu ilə reaksiyaya daxil olur?', NULL::text, '{"A": "$\\mathrm{Fe(OH)_{2}}$ t →", "B": "$\\mathrm{Ca + H_{2}O}$ →", "C": "$\\mathrm{Zn(OH)_{2}}$ t →", "D": "$\\mathrm{KH + H_{2}O}$ →", "E": "$\\mathrm{Mg(OH)_{2}}$ t →"}', 'C', '3', 'Natrium-hidroksid məhlulu ilə amfoter və turşu xassəli maddələr reaksiyaya daxil olur, əsasi xassəli maddələr reaksiyaya daxil olmur: $\mathrm{Zn(OH)_{2}}$ t → $\mathrm{H_{2}O + ZnO}$ [amfoter oksid] $\mathrm{ZnO + 2NaOH \rightarrow Na_{2}ZnO_{2} + H_{2}O}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №73', 'KIM-0193_izah.png'),
  ('KIM-0194', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', '3,36 l (n.ş.) $\mathrm{H^{2}}$ alınan zaman $\mathrm{NaOH}$-ın suda məhlulu ilə neçə qram alüminium reaksiyaya daxil olar? $\mathrm{A_{r}(Al)=27}$', NULL::text, '{"A": "5,4", "B": "18", "C": "9", "D": "3,6", "E": "2,7"}', 'E', '3', 'x q 3,36 litr 2Al + $\mathrm{2NaOH + 2H_{2}O \rightarrow 2NaAlO_{2} + 3H_{2}}$ 2 · 27 3 · 22,4 x = 2,7 q', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №74', 'KIM-0194_izah.png'),
  ('KIM-0195', 'Üzvi kimya', 'Alkanlar', 'qapali', 'Hansı alkanın 4,4 qramının tam yanmasından 6,72 l $\mathrm{CO_{2}}$ alınar (n.ş.)? $\mathrm{A_{r}(C)}$ = 12, $\mathrm{A_{r}(H)}$ = 1', NULL::text, '{"A": "$\\mathrm{C_{5}H_{12}}$", "B": "$\\mathrm{C_{3}H_{8}}$", "C": "$\\mathrm{C_{4}H_{10}}$", "D": "$\\mathrm{CH_{4}}$", "E": "$\\mathrm{C_{2}H_{6}}$"}', 'B', '3', 'ᵥ(CO2) = 6,72 : 22,4 = 0,3 mol 4,4 q 0,3 mol $\mathrm{C_{n}H_{2n+2} + xO_{2} \rightarrow nCO_{2}}$ + (n + $\mathrm{1)H_{2}O}$ 14n + 2 q n mol 4,4n = 4,2n + 0,6 0,2n = 0,6 n = 3 $\mathrm{[C_{3}H_{8}]}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №75', 'KIM-0195_izah.png'),
  ('KIM-0196', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Hansı duzun parçalanması nəticəsində oksigen alınmır?', NULL::text, '{"A": "$\\mathrm{Pb(NO_{3})_{2}}$", "B": "$\\mathrm{Al(NO_{3})_{3}}$", "C": "$\\mathrm{Hg(NO_{3})_{2}}$", "D": "$\\mathrm{KNO_{3}}$", "E": "$\\mathrm{NH_{4}NO_{3}}$"}', 'E', '3', '$\mathrm{NH_{4}NO_{3}}$ t → $\mathrm{N_{2}O + 2H_{2}O}$ $\mathrm{2KNO_{3}t \rightarrow 2KNO_{2}+}$ $\mathrm{O_{2}}$ $\mathrm{4Al(NO_{3})_{3}t \rightarrow 2Al_{2}O_{3} + 12NO_{2} + 3O_{2}}$ $\mathrm{Hg(NO_{3})_{2}t \rightarrow Hg + 2NO_{2} + O_{2}}$ $\mathrm{2Pb(NO_{3})_{2}t \rightarrow 2PbO + 4NO_{2} + O_{2}}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №76', 'KIM-0196_izah.png'),
  ('KIM-0197', 'Qeyri-üzvi kimya', 'Halogenlər', 'qapali', 'Halogenlər Kütləsi (q) Halogenlə reaksiyaya sərf olunan kaliumun mol sayı $\mathrm{F_{2}}$ a $\mathrm{n_{1}}$ $\mathrm{Br_{2}}$ a $\mathrm{n_{2}}$ $\mathrm{Cl_{2}}$ a $\mathrm{n_{3}}$ $\mathrm{n_{1},}$ $\mathrm{n_{2}}$ və $\mathrm{n_{3}}$ arasındakı doğru münasibəti müəyyən edin. $\mathrm{A_{r}(F)=19}$; $\mathrm{A_{r}(Cl)=35,5}$; $\mathrm{A_{r}(Br)=80}$', 'KIM-0197.png', '{"A": "$\\mathrm{n_{2}>n_{3}>n_{1}}$", "B": "$\\mathrm{n_{1}>n_{2}>n_{3}}$", "C": "$\\mathrm{n_{2}>n_{1}>n_{3}}$", "D": "$\\mathrm{n_{1}>n_{3}>n_{2}}$", "E": "$\\mathrm{n_{3}>n_{1}>n_{2}}$"}', 'D', '3', 'Halogenlərin nisbi molekul kütləsi artdıqca onlarla reaksiyaya sərf olunan kaliumun mol sayı azalır. Yəni, nisbi molekul kütləsi az olan halogenlə reaksiyaya daha çox kalium sərf olunur: $\mathrm{n_{1}>}$ $\mathrm{n_{3}>}$ $\mathrm{n_{2}}$', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №77', 'KIM-0197_izah.png'),
  ('KIM-0199', 'Ümumi kimya', 'Elektroliz', 'qapali', 'Kalium-sulfatın suda məhlulunun elektrolizi zamanı katodda 30 mol qaz alınır. Anodda neçə mol qaz alınar?', NULL::text, '{"A": "10", "B": "15", "C": "20", "D": "60", "E": "30"}', 'B', '3', '30 mol x mol $\mathrm{K_{2}SO_{4} + 2H_{2}O \rightarrow 2H_{2} + K_{2}SO_{4} + O_{2}}$ 2 mol 1 mol x = 15 mol', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №79', 'KIM-0199_izah.png'),
  ('KIM-0200', 'Qeyri-üzvi kimya', 'Hidrogen, oksigen, su', 'qapali', 'Guruldayıcı qazın tərkibi Qarışıqda qazların: mol miqdarı kütləsi (q) $\mathrm{O_{2}}$ a c $\mathrm{H_{2}}$ b d Hansı münasibətlər doğrudur? $\mathrm{A_{r}(O)=16,}$ $\mathrm{A_{r}(H)=1}$ I. 2 b a = II. 2 a b = III. 8 d c = IV. 8 c d = V. 4 d c =', 'KIM-0200.png', '{"A": "I, III", "B": "I, IV", "C": "II, IV", "D": "II, III", "E": "I, V"}', 'B', '3', '2 həcm $\mathrm{H_{2}}$ və 1 həcm $\mathrm{O_{2}}$ qarışığı “guruldayıcı qaz” adlanır: a = 1 mol c = 1 · 32 = 32 q b = 2 mol d = 2 · 2 = 4 q I. doğru; b a = IV. doğru; 8 c d =', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №80', 'KIM-0200_izah.png'),
  ('KIM-0201', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', 'Hansı monomerin polimerləşməsindən izopren kauçuku alınır?', 'KIM-0201.png', '{"A": "$\\mathrm{CH_{2}}$ C $\\mathrm{CH_{2}}$ $\\mathrm{CH_{3}}$ $\\mathrm{CH_{3}}$", "B": "$\\mathrm{CH_{2}}$ $\\mathrm{CH}$ $\\mathrm{CH_{3}}$", "C": "$\\mathrm{CH}$ $\\mathrm{CH}$ $\\mathrm{CH}$ $\\mathrm{CH_{2}}$ $\\mathrm{CH_{3}}$", "D": "$\\mathrm{CH_{2}}$ C $\\mathrm{CH}$ $\\mathrm{CH_{2}}$ $\\mathrm{CH_{3}}$", "E": "$\\mathrm{CH_{2}}$ C $\\mathrm{CH}$ $\\mathrm{CH_{3}}$ $\\mathrm{CH_{3}CH_{3}}$"}', 'D', '3', 'İzoprenin polimerləşməsindən izopren kauçuku alınır: $\mathrm{CH_{2}}$ C $\mathrm{CH}$ $\mathrm{CH_{2}}$ $\mathrm{CH_{3}}$ [izopren; 2-metilbutadien-1,3]', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №81', 'KIM-0201_izah.png'),
  ('KIM-0202', 'Ümumi kimya', 'Oksidləşmə-reduksiya reaksiyaları', 'qapali', 'H2SO4(qatı) + $\mathrm{Ag}$ → Hansı sxemlər reaksiyaya uyğundur? 1. $\mathrm{Ag^{0}}$ – 1e– → $\mathrm{Ag^{+1}}$ 2. $\mathrm{S^{+6}+}$ 8e– → S–2 3. $\mathrm{Ag^{+1}+}$ 1e– → $\mathrm{Ag^{0}}$ 4. $\mathrm{S^{+6}+}$ 2e– → S+4', 'KIM-0202.png', '{"A": "3, 4", "B": "2, 3", "C": "2, 4", "D": "1, 2", "E": "1, 4"}', 'E', '3', '+6 0 +1 +4 H2SO4(qatı) + $\mathrm{Ag \rightarrow Ag_{2}SO_{4} + SO_{2} + H_{2}O}$ 1. doğru; $\mathrm{Ag^{0}}$ – 1e– → $\mathrm{Ag^{+1}}$ 4. doğru; $\mathrm{S^{+6}+}$ 2e– → S+4', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №82', 'KIM-0202_izah.png'),
  ('KIM-0203', 'Ümumi kimya', 'Məhlullar', 'aciq_eded', 'Su əlavə olunandan sonra duzun məhlulda kütlə payını (%) hesablayın. 190 q 10%-li $\mathrm{NaCl}$ məhlulu 10 q $\mathrm{H_{2}O}$', NULL::text, NULL::text, '9,5', '3', '190 q 10%-li məhlulda: $\mathrm{m_{x}(NaCl)}$ = 190 · 0,1 = 19 q mməh(son) = 190 + 10 = 200 q 200 q (məhlul) ---- 100% 19 q $\mathrm{(m_{x})}$ ---- x% x = 9,5%', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №83', 'KIM-0203_izah.png'),
  ('KIM-0204', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'aciq_eded', 'Azot və hidrogendən ibarət 360 mol qaz qarışığının reaksiyasından sonra yalnız 40 mol hidrogen artıq qalarsa, ilkin qaz qarışığında neçə mol hidrogen olmuşdur?', NULL::text, NULL::text, '280', '3', 'Reaksiyaya sərf olunan qaz qarışığı: 360 – 40 = 320 mol $\mathrm{N_{2} + 3H_{2} \rightarrow 2NH_{3}}$ 1 mol 3 mol 4 mol qarışığın ---- 1 mol $\mathrm{(N_{2})}$ 320 mol qarışığın ---- x mol $\mathrm{(N_{2})}$ x = 80 mol Başlanğıc qarışıqdakı $\mathrm{H_{2}}$ – nin mol sayı = 360 – 80 = 280', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №84', 'KIM-0204_izah.png'),
  ('KIM-0205', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'aciq_eded', '22,4 l (n.ş.) $\mathrm{CH_{4}}$ yananda 900 kC istilik ayrılır. 2700 kC istilik almaq üçün neçə litr (n.ş.) $\mathrm{CH_{4}}$ yandırılmalıdır?', NULL::text, NULL::text, '67,2', '3', 'x litr 2700 kC $\mathrm{CH_{4} + 2O_{2} \rightarrow CO_{2} + 2H_{2}O}$ + Q kC x = 3 · 22,4 = 67,2 litr 22,4 litr 900 kC', '{1}', '2025', '2025-06-01 qəbul, I qrup, A variantı №85', 'KIM-0205_izah.png'),
  ('KIM-0211', 'Üzvi kimya', 'Üzvi birləşmələrin quruluşu və nomenklaturası', 'qapali', 'Homoloqlar Ümumi olan əlamətlər A x B x-i müəyyən edin. 1. Eyni sinfə aiddirlər 2. Bütün fiziki xassələri eynidir 3. Eyni kimyəvi elementlərdən ibarətdir 4. Nisbi molekul kütlələri eynidir 5. Molekulunda kimyəvi rabitələrin sayı eynidir', 'KIM-0211.png', '{"A": "1, 2", "B": "4, 5", "C": "3, 5", "D": "1, 3", "E": "2, 4"}', 'D', '3', 'Homoloqlar bir-birindən bir və ya bir neçə metilen qrupu $\mathrm{(CH_{2})}$ qədər fərqlənir, eyni sinfə aid olur; eyni kimyəvi elementlərdən təşkil olunur, fiziki xassələri, nisbi molekul kütlələri və molekullarında kimyəvi rabitələrin sayı fərqli olur.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №31', 'KIM-0211_izah.png'),
  ('KIM-0212', 'Üzvi kimya', 'Üzvi birləşmələrin quruluşu və nomenklaturası', 'qapali', 'Maddələr Molekulunda metilen qruplarının sayı qliserin X yağ turşusu Y propanal Z X, Y və Z -i müqayisə edin.', 'KIM-0212.png', '{"A": "X=Z >Y", "B": "X=Y >Z", "C": "Y>Z >X", "D": "X>Y>Z", "E": "X>Z >Y"}', 'B', '3', 'Metilen qrupu: – $\mathrm{CH_{2}}$ – X = 2 $\mathrm{CH_{3} - CH_{2} - CH_{2} - COOH}$ Y = 2 $\mathrm{CH_{3} - CH_{2} - CHO}$ Z = 2', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №32', 'KIM-0212_izah.png'),
  ('KIM-0213', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', 'Hansı reaksiya həm birləşmə, həm də oksidləşmə- reduksiya reaksiyasıdır?', NULL::text, '{"A": "$\\mathrm{P_{2}O_{5} + H_{2}O}$ →", "B": "$\\mathrm{Cu + HNO_{3}}$ →", "C": "$\\mathrm{CaCO_{3} + CO_{2} + H_{2}O}$ →", "D": "$\\mathrm{NO_{2} + O_{2} + H_{2}O}$ →", "E": "K + $\\mathrm{H_{2}O}$ →"}', 'D', '3', '$\mathrm{CaCO_{3} + CO_{2} + H_{2}O \rightarrow Ca(HCO_{3})_{2}}$ oksidləşmə-reduksiya reaksiyası deyil $\mathrm{P_{2}O_{5} + 3H_{2}O \rightarrow 2H_{3}PO_{4}}$ oksidləşmə-reduksiya reaksiyası deyil 2K + $\mathrm{2H_{2}O \rightarrow 2KOH}$ $\mathrm{+H_{2}}$ birləşmə reaksiyası deyil $\mathrm{4NO_{2} + O_{2} + 2H_{2}O \rightarrow 4HNO_{3}}$ həm birləşmə, həm də oksidləşmə-reduksiya reaksiyasıdır 3Cu + $\mathrm{8HNO_{3} \rightarrow 3Cu(NO_{3})_{2} + 2NO + 4H_{2}O}$ birləşmə reaksiyası deyil', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №33', 'KIM-0213_izah.png'),
  ('KIM-0214', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', '$\mathrm{A_{2}+}$ 2B → 2C homogen reaksiyasında müəyyən müddət ərzində A2-nin qatılığı 0,25 l mol -dən 0,22 l mol -ə qədər azalmışdır. Bu müddət ərzində B-nin qatılığının azalmasını ( l mol ) hesablayın.', 'KIM-0214.png', '{"A": "0,06", "B": "0,03", "C": "0,25", "D": "0,5", "E": "0,125"}', 'A', '3', 'A2-nin sərf olunan qatılığı: 0,25 – 0,22 = 0,03 mol/litr B maddəsi isə $\mathrm{A_{2}}$ maddəsindən 2 dəfə çox yəni, 0,03 · 2 = 0,06 mol/litr sərf olunur.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №34', 'KIM-0214_izah.png'),
  ('KIM-0215', 'Qeyri-üzvi kimya', 'Azot və birləşmələri', 'qapali', 'Reaksiyalara əsasən X, Y və Z metallarını kimyəvi → aktivliyinə görə müqayisə edin. $\mathrm{2XNO_{3}}$ t → $\mathrm{2XNO_{2}+}$ $\mathrm{O_{2}}$ $\mathrm{Y(NO_{3})_{2}}$ t → Y + $\mathrm{2NO_{2}+}$ $\mathrm{O_{2}}$ $\mathrm{4Z(NO_{3})_{3}}$ t → $\mathrm{2Z_{2}O_{3}+}$ $\mathrm{12NO_{2}+}$ $\mathrm{3O_{2}}$', NULL::text, '{"A": "Y>X>Z", "B": "X>Y>Z", "C": "Y>Z>X", "D": "Z>Y>X", "E": "X>Z>Y"}', 'E', '3', 'Nitrat duzlarının parçalanma reaksiyalarına əsasən X aktiv ($\mathrm{Na}$, K və s.), Y passiv ($\mathrm{Hg}$, $\mathrm{Ag}$ və s.), Z isə orta aktiv ( $\mathrm{Mg}$, $\mathrm{Zn}$ və s.) metallar olduğundan kimyəvi aktivliyinə görə X > Z > Y müqayisəsi doğru olur.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №35', 'KIM-0215_izah.png'),
  ('KIM-0216', 'Ümumi kimya', 'Atomun quruluşu və dövri sistem', 'qapali', 'Xlor hansı birləşmələrdə … $\mathrm{3s^{n}3p^{m}3d^{n}}$ elektron formuluna uyğundur? 1. $\mathrm{Cl_{2}O_{5}}$ 2. $\mathrm{HClO}$ 3. $\mathrm{HClO_{2}}$ 4. $\mathrm{HClO_{3}}$', NULL::text, '{"A": "3, 4", "B": "2, 4", "C": "2, 3", "D": "1, 3", "E": "1, 4"}', 'E', '3', 'Xlorun normal və həyəcanlanmış vəziyyətlərə uyğun valentlikləri: … $\mathrm{3s^{2}3p^{5}3d^{0}}$ (I valentli) … $\mathrm{3s^{2}3p^{4}3d^{1}}$ (III valentli) … $\mathrm{3s^{2}3p^{3}3d^{2}(V}$ valentli) … $\mathrm{3s^{1}3p^{3}3d^{3}}$ (VII valentli) …3sn3pm3dn elektron formuluna …3s23p33d2həyəcanlanmış halı uyğun olur ki, bu halda xlor V valentli olur $\mathrm{(Cl_{2}O_{5}}$ və $\mathrm{HClO_{3}).}$', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №36', 'KIM-0216_izah.png'),
  ('KIM-0219', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', 'Etilenin hidrogen-xloridlə reaksiya məhsuluna natrium ilə təsir etdikdə hansı maddə alınar?', NULL::text, '{"A": "3-metilbutan", "B": "n-butan", "C": "2-metilpropan", "D": "2-metilbutan", "E": "2,3-dimetilpropan"}', 'B', '3', '$\mathrm{C_{2}H_{4} + HCl \rightarrow C_{2}H_{5}Cl}$ $\mathrm{2C_{2}H_{5}Cl}$ + 2Na → $\mathrm{2NaCl + CH_{3} - CH_{2} - CH_{2} - CH_{3}}$ [n-butan]', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №39', 'KIM-0219_izah.png'),
  ('KIM-0220', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'Qapalı qabda baş verən $\mathrm{Cr}$ + HNO3(qatı) t → $\mathrm{Cr(NO_{3})_{n}+}$ X↑ + $\mathrm{H_{2}O}$ reaksiyasına əsasən doğru ifadələri müəyyən edin. $\mathrm{A_{r}(N)=14}$; $\mathrm{A_{r}(O)=16}$; $\mathrm{A_{r}(H)=1}$; Morta(hava)=29 q/mol 1. X qazını oksidləşmə məhsulunun parçalanmasından almaq olar. 2. Reaksiyaya daxil olan turşunun 75%-i duzun alınmasına sərf olunur. 3. X qazının sıxlığı havanın sıxlığından (n.ş.) azdır. 4. 6 mol su əmələ gəldikdə reduksiyaedici $\mathrm{9N_{A}}$ elektron verir. 5. Reduksiya məhsulu duz əmələ gətirməyən oksiddir.', NULL::text, '{"A": "1, 2, 4", "B": "3, 4, 5", "C": "1, 3, 5", "D": "1, 2, 3", "E": "2, 4, 5"}', 'E', '3', '$\mathrm{Cr}$ + 4HNO3(qatı) t → $\mathrm{Cr(NO_{3})_{3}+}$ $\mathrm{NO}$ ↑ + $\mathrm{2H_{2}O}$ 1. səhv; $\mathrm{NO}$ qazı $\mathrm{Cr(NO_{3})_{3}}$ duzunun parçalanmasından alınmır. 2. doğru; reaksiyaya daxil olan 4 mol turşunun 3 molu (75%-i) duzun alınmasına sərf olunur 3. səhv; 30/22,4 ˃ 29/22,4 olduğu üçün $\mathrm{D_{NO}}$ ˃ Dhava 4. doğru; $\mathrm{3N_{A}}$ elektron ------- 2 mol su $\mathrm{9N_{A}}$ elektron ------- x mol su / x = 6 mol $\mathrm{H_{2}O}$ 5. doğru; reduksiya məhsulu $\mathrm{(NO)}$ duz əmələgətirməyən oksiddir', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №40', 'KIM-0220_izah.png'),
  ('KIM-0221', 'Üzvi kimya', 'Aminlər və aminturşular', 'qapali', '3-aminpropan turşusu ilə izomer olan maddəni göstərin.', 'KIM-0221.png', '{"A": "$\\mathrm{NH_{2}}$ $\\mathrm{(CH_{2})_{3}}$ $\\mathrm{COOH}$", "B": "$\\mathrm{C_{2}H_{5}COONH_{4}}$", "C": "$\\mathrm{NH_{2}(CH_{2})_{4}COOH}$", "D": "$\\mathrm{NH_{2}}$ C $\\mathrm{COOH}$ $\\mathrm{CH_{3}}$ $\\mathrm{CH_{3}}$", "E": "$\\mathrm{NH_{2}}$ $\\mathrm{CH}$ $\\mathrm{COOH}$ $\\mathrm{CH_{3}}$"}', 'E', '3', '3-aminpropan turşusu: $\mathrm{H_{2}N - CH_{2} - CH_{2} - COOH}$ $\mathrm{H_{2}N - CH_{2} - CH_{2} - COOH}$ və $\mathrm{NH_{2}}$ $\mathrm{CH}$ $\mathrm{COOH}$ $\mathrm{CH_{3}}$ izomerdirlər. Çunki hər iki maddə $\mathrm{C_{3}H_{7}NO_{2}}$ formuluna malikdir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №41', 'KIM-0221_izah.png'),
  ('KIM-0223', 'Üzvi kimya', 'Karbon turşuları', 'qapali', 'Maddələr Molekulunda karbon atomlarının sayı Molyar kütləsi mol q ? ? ? ? ? ? Doymuş biratomlu spirt n m Doymuş birəsaslı karbon turşusu n x x-i müəyyən edin. $\mathrm{A_{r}(C)=12}$; $\mathrm{A_{r}(H)=1}$; $\mathrm{A_{r}(O)=16}$', 'KIM-0223.png', '{"A": "m + 14", "B": "m + 32", "C": "m – 16", "D": "m + 16", "E": "m – 14"}', 'A', '3', '$\mathrm{M_{r}(C_{n}H_{2n+2}O)}$ = 14n + 18 [m] $\mathrm{M_{r}(C_{n}H_{2n}O_{2})}$ = 14n + 32 [m + 14]', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №43', 'KIM-0223_izah.png'),
  ('KIM-0224', 'Üzvi kimya', 'Karbohidratlar', 'qapali', 'Fotosintez prosesi: sərf olunan $\mathrm{CO_{2}}$-nin kütləsi, q sərf olunan $\mathrm{H_{2}O}$-un miqdarı, mol alınan $\mathrm{O_{2}}$-nin kütləsi, q m n m – 14,4 m+n cəmini hesablayın. $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(O)=16,}$ $\mathrm{A_{r}(H)=1}$', 'KIM-0224.png', '{"A": "52", "B": "60", "C": "54", "D": "56", "E": "58"}', 'C', '3', '6·44 q 6·32 q $\mathrm{6CO_{2}+}$ $\mathrm{6H_{2}O \rightarrow C_{6}H_{12}O_{6}+}$ $\mathrm{6O_{2}}$ 6 · 44 – 6 · 32 = 72 q fərq 72 q fərq ---- 6·44 q $\mathrm{(CO_{2})}$ 14,4 q fərq ---- m q $\mathrm{(CO_{2})}$ / m = 52,8 q $\mathrm{(CO_{2}}$ sərf olunur) 72 q fərq ----- 6 mol $\mathrm{(H_{2}O}$ əmələ gəlir) 14,4 q fərq ----- n mol $\mathrm{(H_{2}O}$ əmələ gəlir) / n = 1,2 mol m + n = 52,8 + 1,2 = 54', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №44', 'KIM-0224_izah.png'),
  ('KIM-0225', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', '$\mathrm{H_{2}S}$ və $\mathrm{N_{2}}$-dən ibarət qaz qarışığının həcmi (n.ş, l) Qaz qarışığından alınan $\mathrm{H_{2}SO_{4}}$-ün maksimum kütləsi (q) 89,6 196 İlkin qaz qarışığındakı $\mathrm{N_{2}}$-in mol payını (%-lə) hesablayın. $\mathrm{M_{r}(H_{2}SO_{4})=98}$', 'KIM-0225.png', '{"A": "60", "B": "40", "C": "80", "D": "50", "E": "75"}', 'D', '3', 'Başlanğıc qaz qarışığının mol sayı: 89,6 : 22,4 = 4 mol $\mathrm{H_{2}S \rightarrow H_{2}SO_{4}}$ 1 mol 98 q 1 mol $\mathrm{(H_{2}S)}$ ---- 98 q $\mathrm{(H_{2}SO_{4})}$ x mol $\mathrm{(H_{2}S)}$ ---- 196 q $\mathrm{(H_{2}SO_{4})}$ / x = 2 mol 4 mol (qarışıq) ----- 100% 2 mol $\mathrm{(H_{2}S)}$ ----- y% / y = 50%', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №45', 'KIM-0225_izah.png'),
  ('KIM-0226', 'Ümumi kimya', 'Kimyəvi rabitə və hibridləşmə', 'qapali', 'Alkan molekulunda $\mathrm{\sigma (sp^{3}-}$ s) rabitələrinin sayı 10-a bərabərdir. Bu alkanın molekulunda hibrid orbitalların sayını müəyyən edin.', NULL::text, '{"A": "12", "B": "30", "C": "20", "D": "16", "E": "24"}', 'D', '3', 'Alkanlarda bütün karbon atomları sp3-hibrid halındadır. Ona görə də $\mathrm{\sigma (sp^{3}}$ – s) rabitələrinin sayı hidrogen atomlarının sayına bərabər olur: $\mathrm{C_{n}H_{2n+2}}$ 2n + 2 = 10 2n = 8 n = 4 $\mathrm{(C_{4}H_{10})}$ Hibrid orbitalların sayı: 4n = 4 · 4 = 16', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №46', 'KIM-0226_izah.png'),
  ('KIM-0227', 'Üzvi kimya', 'Karbohidratlar', 'qapali', 'Qlükozanın qıcqırmasından alınan üzvi maddə molekulunda karbon atomlarının sayı Qlükozanın qıcqırmasından alınan üzvi maddə molekulunda hidrogen atomlarının sayı 4 x 3 y 2 z x, y və z-i müəyyən edin. x y z', 'KIM-0227.png', '{"A": "4 6 5", "B": "8 6 2", "C": "8 6 6", "D": "6 8 6", "E": "6 8 5"}', 'C', '3', '$\mathrm{C_{6}H_{12}O_{6} \rightarrow 2CO_{2} + 2H_{2} + C_{4}H_{8}O_{2}}$ (x = 8) $\mathrm{C_{6}H_{12}O_{6} \rightarrow 2C_{3}H_{6}O_{3}}$ (y = 6) $\mathrm{C_{6}H_{12}O_{6} \rightarrow 2CO_{2} + C_{2}H_{5}OH}$ (z = 6)', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №47', 'KIM-0227_izah.png'),
  ('KIM-0228', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'qapali', '$\mathrm{X_{2}SO_{4}\cdot}$ $\mathrm{nH_{2}O}$ kristalhidratında hidrogen atomları sayının oksigen atomlarının sayına olan nisbəti 10:7 kimidir. n-i müəyyən edin.', NULL::text, '{"A": "7", "B": "10", "C": "2", "D": "6", "E": "5"}', 'B', '3', '2 10 4 7 n n = + 14 10 40 n n = + 4 40 n = 10 n =', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №48', 'KIM-0228_izah.png'),
  ('KIM-0229', 'Üzvi kimya', 'Aromatik karbohidrogenlər', 'qapali', 'X və Z maddələri üçün ümumi olan nədir? $\mathrm{3C_{2}H_{2}}$ X Y Z → → → Cakt,t +C2H4,kat,t kat,t $\mathrm{-H_{2}}$ 1. Karbonun kütlə payı 2. Ümumi formulları 3. Bromlu suyu rəngsizləşdirməsi 4. Karbon atomlarının hibrid vəziyyəti 5. Polimerləşmə reaksiyasına daxil olması 6. Aromatik karbohidrogen olması', NULL::text, '{"A": "2, 3, 5", "B": "1, 2, 5", "C": "2, 5, 6", "D": "1, 4, 6", "E": "1, 3, 4"}', 'D', '3', '$\mathrm{3C_{2}H_{2} \rightarrow C_{6}H_{6}}$ (X – benzol) $\mathrm{C_{6}H_{6} + C_{2}H_{4} \rightarrow C_{6}H_{5} - C_{2}H_{5}}$ $\mathrm{[C_{8}H_{8}]}$ (Y – etilbenzol) $\mathrm{C_{6}H_{5} - C_{2}H_{5} \rightarrow H_{2} + C_{6}H_{5} - CH = CH_{2}}$ (Z – stirol) Benzol və stirolda karbonun kütlə payı və karbon atomlarının hibrid vəziyyəti eynidir. Hər ikisi aromatik karbohidrogendir. Benzoldan fərqli olaraq stirol bromlu suyu rəngsizləşdirir və polimerləşir.', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №49', 'KIM-0229_izah.png'),
  ('KIM-0230', 'Qeyri-üzvi kimya', 'Metallar', 'qapali', 'X + $\mathrm{Fe}$ → Y + $\mathrm{KOH}$ → Z +X → Y X, Y və Z maddələrini müəyyən edin. X Y Z', 'KIM-0230.png', '{"A": "$\\mathrm{HCl}$ $\\mathrm{FeCl_{3}}$ $\\mathrm{Fe(OH)_{3}}$", "B": "$\\mathrm{HCl}$ $\\mathrm{FeCl_{2}}$ $\\mathrm{Fe(OH)_{2}}$", "C": "$\\mathrm{Cl_{2}}$ $\\mathrm{FeCl_{3}}$ $\\mathrm{Fe(OH)_{2}}$", "D": "$\\mathrm{Cl_{2}}$ $\\mathrm{FeCl_{2}}$ $\\mathrm{Fe(OH)_{2}}$", "E": "$\\mathrm{HCl}$ $\\mathrm{FeCl_{2}}$ $\\mathrm{Fe(OH)_{3}}$"}', 'B', '3', '$\mathrm{HCl + Fe \rightarrow FeCl_{2} + KOH \rightarrow Fe(OH)_{2}}$ $\mathrm{HCl \rightarrow FeCl_{2}}$', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №50', 'KIM-0230_izah.png'),
  ('KIM-0231', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'qapali', 'x + y = 0,75 olduqda, $\mathrm{A_{2}B}$ birləşməsinin dissosiasiya dərəcəsini (%-lə) hesablayın. Dissosiasiyasından alınan ionların mol miqdarı y x $\mathrm{B_{2} - A^{+}}$ 0,2 → 0,6 A2B-nin mol miqdarı', 'KIM-0231.png', '{"A": "30", "B": "65", "C": "35", "D": "75", "E": "45"}', 'D', '3', '$\mathrm{A_{2}B}$ ↔ $\mathrm{2A^{+} + B^{2-}}$ 1 mol 2 mol 1 mol 1 mol $\mathrm{A_{2}B}$ --- 2 mol $\mathrm{(A^{+})}$ 0,2 mol --- x mol $\mathrm{(A^{+})}$ / x = 0,4 mol $\mathrm{[A^{+}}$ ə/gəlməlidir] 1 mol $\mathrm{A_{2}B}$ --- 1 mol $\mathrm{(B^{2-})}$ 0,6 mol --- y mol $\mathrm{(B^{2-})}$ / y = 0,6 mol $\mathrm{[B^{2-}}$ ə/gəlməlidir] Əmələ gəlməli olan ionların cəmi mol sayı: 0,4 + 0,6 = 1 1 mol ion ---- 100% 0,75 mol ion ---- k% / k = 75%', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №51', 'KIM-0231_izah.png'),
  ('KIM-0232', 'Ümumi kimya', 'Məhlullar', 'qapali', 'I 60 q y%-li məhlul II a q x%-li məhlul a q y%-li məhlul 100 q x%-li məhlul Eyni maddənin məhlullarını qarışdırdıqda I qabda 19%-li, II qabda isə 22%-li məhlul alınarsa, y-i hesablayın.', 'KIM-0232.png', '{"A": "16", "B": "34", "C": "28", "D": "22", "E": "35"}', 'B', '3', 'Müxtəlif qatılıqlı və kütləli iki məhlulu qarışdıran zaman alınan son məhlulda maddənin kütlə payı: ωson= $\mathrm{(m_{1}\cdot}$ $\mathrm{\omega _{1} + m_{2}\cdot}$ $\mathrm{\omega _{2})}$ : $\mathrm{(m_{1} + m_{2})}$ Müxtəlif qatılıqlı, eyni kütləli iki məhlulu qarışdıran zaman alınan məhlulda maddənin kütlə payı: ωson= $\mathrm{(\omega _{1} + \omega _{2})}$ : 2 Düsturlara əsasən sistem tənlik quraq: (100 60 ) 19 100 60 44 x y x y + ? = ? + ? ?+ = ? 100 60 3040 44 x y x y + = ? ?+ = ? 10 6 304 44 x y x y + = ? ?+ = ? 10 6 304 10 10 440 x y x y + = ? ? + = ? 4 136 y = 34 y =', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №52', 'KIM-0232_izah.png'),
  ('KIM-0233', 'Qeyri-üzvi kimya', 'Qeyri-üzvi maddələrin sinifləri', 'aciq_eded', 'Qarışığın tərkibi Mol sayı Qarışığın kütləsi, q Su ilə tam reaksiyasından alınan qələvilər qarışığının kütləsi, q $\mathrm{KH}$ n m m + 4,8 $\mathrm{CaH_{2}}$ n n-i hesablayın. $\mathrm{A_{r}(Ca)=40}$; $\mathrm{A_{r}(K)=39}$; $\mathrm{A_{r}(H)=1}$; $\mathrm{A_{r}(O)=16}$', 'KIM-0233.png', NULL::text, '0,1', '3', 'n mol x q $\mathrm{KH + H_{2}O \rightarrow KOH + H_{2}}$ 1 mol 56 q n mol ----- x q 1 mol ----- 56 q / x = 56n q [$\mathrm{KOH}$ əmələ gəlir] n mol y q $\mathrm{CaH_{2} + 2H_{2}O \rightarrow Ca(OH)_{2} + 2H_{2}}$ 1 mol 74 q n mol ----- y q 1 mol ----- 74 q / y = 74n $\mathrm{[Ca(OH)_{2}}$ əmələ gəlir] 40 42 56 74 4,8 n n m n n m + = ? ? + = + ? 82 130 4,8 n m n m = ? ? = + ? 130 4,8 n n = + 4,8 n = 0,1 n =', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №53', 'KIM-0233_izah.png'),
  ('KIM-0234', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'aciq_eded', 'Polimerlər Polimerləşmə dərəcəsi Makromolekulunda metilen qruplarının sayı neylon n x kapron n y x : y nisbətini hesablayın.', 'KIM-0234.png', NULL::text, '2', '3', '[– $\mathrm{HN - (CH_{2})_{6} - NH - CO - (CH_{2})_{4} - CO - ]_{n}}$ [neylon, x = 10] [– $\mathrm{HN - (CH_{2})_{5} - CO - ]_{n}}$ [kapron, y = 5] x : y = 10 : 5 = 2', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №54', 'KIM-0234_izah.png'),
  ('KIM-0236', 'Ümumi kimya', 'Kimyəvi tənliklər üzrə hesablamalar', 'aciq_eded', 'Maddə Mol miqdarı Tam yanmasından alınan maddələrin ümumi mol miqdarı $\mathrm{C_{5}H_{n}O}$ 0,1 1 Yanan maddə molekulunda neçə atom vardır?', 'KIM-0236.png', NULL::text, '16', '3', '0,1 mol $\mathrm{(C_{5}H_{n}O)}$ ------- 1 mol (məhsul alınır) 1 mol $\mathrm{(C_{5}H_{n}O)}$ ------- x mol (məhsul alınır) x = 10 mol (məhsul alınır) $\mathrm{C_{5}H_{n}O}$ + y $\mathrm{O_{2} \rightarrow 5CO_{2} + n/2H_{2}O}$ 5 + n/2 = 10 n/2 = 5 n = 10 $\mathrm{[C_{5}H_{10}O}$ molekulunda 16 atom olur]', '{4}', '2025', '2025-06-01 qəbul, IV qrup, A variantı №56', 'KIM-0236_izah.png')
       ) as v(code, section, topic, type, body, image_path, options, correct, difficulty, solution,
              groups, year, source_ref, solution_image_path)
  join subjects s on s.slug = 'kimya'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = v.section
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = v.topic
on conflict (code) do update set
  topic_id = excluded.topic_id, type = excluded.type, body = excluded.body, image_path = excluded.image_path,
  options = excluded.options, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty,
  solution = excluded.solution, exam_levels = excluded.exam_levels, groups = excluded.groups,
  year = excluded.year, source = excluded.source, source_ref = excluded.source_ref,
  is_active = excluded.is_active, solution_image_path = excluded.solution_image_path;

-- 4) every approved question must now exist (a missing topic would silently drop a row from the join)
do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('KIM-0001', 'KIM-0002', 'KIM-0003', 'KIM-0004', 'KIM-0007', 'KIM-0008', 'KIM-0011', 'KIM-0012', 'KIM-0013', 'KIM-0014', 'KIM-0015', 'KIM-0016', 'KIM-0017', 'KIM-0018', 'KIM-0019', 'KIM-0020', 'KIM-0021', 'KIM-0023', 'KIM-0024', 'KIM-0026', 'KIM-0031', 'KIM-0032', 'KIM-0033', 'KIM-0034', 'KIM-0035', 'KIM-0036', 'KIM-0037', 'KIM-0038', 'KIM-0039', 'KIM-0040', 'KIM-0041', 'KIM-0042', 'KIM-0046', 'KIM-0048', 'KIM-0049', 'KIM-0051', 'KIM-0053', 'KIM-0055', 'KIM-0061', 'KIM-0062', 'KIM-0063', 'KIM-0064', 'KIM-0068', 'KIM-0069', 'KIM-0070', 'KIM-0071', 'KIM-0072', 'KIM-0073', 'KIM-0074', 'KIM-0079', 'KIM-0080', 'KIM-0081', 'KIM-0082', 'KIM-0083', 'KIM-0084', 'KIM-0085', 'KIM-0086', 'KIM-0091', 'KIM-0092', 'KIM-0093', 'KIM-0094', 'KIM-0095', 'KIM-0097', 'KIM-0098', 'KIM-0099', 'KIM-0100', 'KIM-0101', 'KIM-0102', 'KIM-0103', 'KIM-0106', 'KIM-0108', 'KIM-0110', 'KIM-0111', 'KIM-0112', 'KIM-0113', 'KIM-0114', 'KIM-0115', 'KIM-0116', 'KIM-0123', 'KIM-0125', 'KIM-0128', 'KIM-0129', 'KIM-0133', 'KIM-0139', 'KIM-0140', 'KIM-0141', 'KIM-0143', 'KIM-0144', 'KIM-0145', 'KIM-0146', 'KIM-0151', 'KIM-0152', 'KIM-0153', 'KIM-0154', 'KIM-0155', 'KIM-0156', 'KIM-0157', 'KIM-0158', 'KIM-0159', 'KIM-0160', 'KIM-0161', 'KIM-0162', 'KIM-0163', 'KIM-0164', 'KIM-0165', 'KIM-0166', 'KIM-0167', 'KIM-0168', 'KIM-0169', 'KIM-0171', 'KIM-0172', 'KIM-0173', 'KIM-0174', 'KIM-0175', 'KIM-0181', 'KIM-0182', 'KIM-0183', 'KIM-0184', 'KIM-0186', 'KIM-0187', 'KIM-0189', 'KIM-0190', 'KIM-0191', 'KIM-0192', 'KIM-0193', 'KIM-0194', 'KIM-0195', 'KIM-0196', 'KIM-0197', 'KIM-0199', 'KIM-0200', 'KIM-0201', 'KIM-0202', 'KIM-0203', 'KIM-0204', 'KIM-0205', 'KIM-0211', 'KIM-0212', 'KIM-0213', 'KIM-0214', 'KIM-0215', 'KIM-0216', 'KIM-0219', 'KIM-0220', 'KIM-0221', 'KIM-0223', 'KIM-0224', 'KIM-0225', 'KIM-0226', 'KIM-0227', 'KIM-0228', 'KIM-0229', 'KIM-0230', 'KIM-0231', 'KIM-0232', 'KIM-0233', 'KIM-0234', 'KIM-0236');
  if n <> 158 then
